-- 1. Дело (карта берётся из уже существующего дела, если она там есть)
insert into cases (id, title, price, intro_text, is_published, map_image_url) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Дело №9704 «Угоревший» — новая версия', 0, 'Понедельник, 25 ноября 1996 года, 9:10. Кабинет начальника следственного отдела ГУВД г. Алматы.

— Садись. Пальто не снимай, батарея всё равно не греет. Вот тебе подарок из Медеуского РОВД — отказной материал. Сартаков Игорь, сорок один год, хозяин базы на Ташкентской, импорт оборудования. Вчера в 09:40 водитель Гринько нашёл его в гараже собственной дачи на Кок-Тобе: за рулём, ключ в зажигании, бак сухой, ворота гаража закрыты. В субботу вечером на Кок-Тобе отключали свет. Грелся в машине, задремал, угорел. Опергруппа управилась за час, вскрытие не назначили — «и так ясно». Мать хочет хоронить, РОВД хочет закрыть, прокуратура хочет, чтобы я подписал.

А я не подпишу, пока ты не посмотришь. Мужик при деньгах, в разводе, база приватизированная — такие у нас сами редко умирают. Тело в морге, Юрий Николаевич Кан ждёт бумагу. Гульнара Сеитова съездит с тобой на дачу, Ринат Абишев посидит на картотеках, доцент Бейсенов из высшей школы МВД на этой неделе у нас консультирует. Даю неделю. Угорел — закроем с чистой совестью. Нет — найди мне, как он оказался за рулём.', false, (select c.map_image_url from cases c join locations l on l.case_id = c.id where l.name = 'ГУВД города Алматы' and c.map_image_url is not null and c.id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' limit 1));

-- 2. Локации
insert into locations (id, case_id, name, image_url, preview_image_url, short_description, map_pos_x, map_pos_y, is_searchable, unlock_evidence_ids) values ('006a31f4-baeb-5b53-9a87-6a397ba18362', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'ГУВД города Алматы', (select image_url from locations where name = 'ГУВД города Алматы' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and image_url is not null limit 1), (select preview_image_url from locations where name = 'ГУВД города Алматы' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and preview_image_url is not null limit 1), 'Здание ГУВД в понедельник утром пахнет мокрыми шинелями, «Космосом» и хлоркой. Батареи чуть тёплые, у дежурного под столом гудит самодельный «козёл» с красной спиралью. В коридорах стрекочут пишущие машинки, за дверью ИВЦ кто-то третий раз подряд ругается по телефону с АТС. Гор из окна не видно: город затянуло смогом, серым и плотным, как вата в старом окне. В подвале — изолятор временного содержания, задержанных водят наверх по лестнице, потому что лифт опять стоит. Морг бюро СМЭ — через двор, в низком корпусе. Там холодно по-настоящему, и это единственное место, где холоду рады.

На вашем столе — тонкая папка Медеуского РОВД: протокол осмотра, фототаблица на шести листах, объяснение водителя. Рядом — чужие дела, перевязанные бечёвкой, и стопка ориентировок на угнанные «девятки». Стул для допрашиваемого стоит у стены, отдельно от стола. На стене карта города с выцветшими флажками: кто-то когда-то отмечал квартирные кражи и бросил. На подоконнике электрочайник, пачка грузинского чая и две пиалы с трещинками. В морге, в журнале приёма, — запись о доставке Сартакова И. и пустая графа там, где должно стоять «назначена экспертиза». Юрий Николаевич Кан курит у служебного входа и ждёт, когда ему дадут бумагу.', 50, 45, false, null);
insert into locations (id, case_id, name, image_url, preview_image_url, short_description, map_pos_x, map_pos_y, is_searchable, unlock_evidence_ids) values ('29196055-161c-5b4e-a38f-352cbf3e5032', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Дача Сартакова на Кок-Тобе', null, null, 'Дорога на Кок-Тобе петляет вверх без единого фонаря. Внизу город лежит в смоге, как в мутной воде, а здесь воздух резкий, с запахом мокрой хвои и печного дыма от соседних дач. На склонах первый снег лежит рваными пятнами, под ногами бурая слякоть, к вечеру она схватывается коркой. Кирпичный двухэтажный дом с тёмными окнами, голые яблони, вдоль забора арык, забитый листвой. Тихо так, что слышно, как под листьями бежит вода. В половине шестого гора уходит в темноту вся сразу, будто кто-то повернул рубильник.

Большие ворота распахнуты, у въезда в грязи каша из следов: РОВД, водитель, «скорая». Рядом с воротами узкая калитка, на её щеколде висит паутина с застрявшими сухими листьями. Арык вдоль забора доверху набит мокрой листвой; у самых ворот листья лежат ровно, только с краю темнеет что-то пластмассовое — то ли крышка, то ли мусор. Гараж кирпичный, ворота железные. Машину РОВД увёз на свою стоянку, на бетоне осталось масляное пятно, на стене — полоса выхлопной копоти. Снаружи, у въезда в гараж, под свесом крыши слякоть сохранила следы: одни узкие, под ледяной коркой, другие крупные, присыпанные тонким снегом, и две параллельные борозды. В папке РОВД — фототаблица: тело за рулём. На крыльце дома стоит мешок угольных брикетов и холодный котёл с открытой дверцей. Под навесом детский велосипед, укрытый клеёнкой. Шланг для полива вмёрз в лёд у бочки.', 72, 64, true, array['43eaf70c-177d-516a-9ab2-7aecc9633e33','e34a96b0-5d0e-5414-9ef3-048071ef84ed']::uuid[]);
insert into locations (id, case_id, name, image_url, preview_image_url, short_description, map_pos_x, map_pos_y, is_searchable, unlock_evidence_ids) values ('78a34a22-6cc3-50d3-b3a7-bf4a481856bc', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Квартира Валентины Петровны на Абая', null, null, 'Сталинка на Абая: высокие потолки, широкий подъезд, лифт с решёткой стоит — свет в доме дали только к обеду. На лестнице пахнет пловом, баурсаками и валерьянкой: к Валентине Петровне с утра идут люди выразить соболезнование. Похорон ещё не было: тело в морге, и никто не знает, когда его отдадут. Зеркала завешены простынями, на кухне соседки режут хлеб и говорят вполголоса; одна из них, в мохеровом берете, то и дело выходит на площадку проветрить от табака. Мужчины курят на балконе, не снимая пальто, — батареи едва тёплые. За окном троллейбус на Абая искрит дугами в мокрых сумерках.

В прихожей, на тумбочке под зеркалом в простыне, стоит телефон, над ним на гвоздике — китайский определитель номера: серая коробочка, красные цифры, кнопка памяти. Рядом блокнот в клетку с карандашом на верёвочке, на открытой странице — цифры и слова учительским почерком, кое-что обведено. В большой комнате портрет Игоря с чёрной лентой, на столе одолженные у соседей тарелки, телевизор накрыт салфеткой. В серванте за стеклом хрусталь, фотография внучки в школьной форме и белый конверт, прислонённый к рюмкам. На подоконнике пачка телеграмм с соболезнованиями.', 47, 55, true, array['54bf13bc-3525-5eec-9441-609d8ee21f59','7ada2011-2720-5b69-8a9c-9291fdad70e9']::uuid[]);
insert into locations (id, case_id, name, image_url, preview_image_url, short_description, map_pos_x, map_pos_y, is_searchable, unlock_evidence_ids) values ('92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'База и офис фирмы на Ташкентской', null, null, 'Бывшая госбаза на Ташкентской: бетонный забор с колючкой, ворота с облупленной звездой, шлагбаум и будка КПП. За забором звенит и искрит трамвай. В лужах радужные пятна солярки, по слякоти буксует «КамАЗ» с китайскими ящиками. Ветер с гор гонит по двору обрывки упаковочной бумаги. В будке охраны жарко от «козла», в конторе холодно и пахнет пылью и копиркой. Над складами уже горят прожекторы, хотя нет и пяти: в промзоне из-за смога темнеет раньше, чем в центре. Жестяная табличка «Территория АО. Посторонним вход воспрещён» прибита поверх старой, госснабовской.

В будке КПП стол, электроплитка, на стене график смен, на столе толстый журнал посетителей в клеёнчатой обложке: фамилии, номера машин, время, подписи, страница за страницей с лета. Охранник Нуртазин сидит на табурете, на ремне у него пейджер агентства. Пепельница из консервной банки полна окурков, половина пепла рядом. В кабинете Ахметова папки стоят по годам, рядом сейф и ксерокс под матерчатым чехлом, на стене календарь с японским джипом. В приёмной у кабинета Сартакова пустой стул водителя и кадка с засохшим фикусом.', 44, 22, true, array['54bf13bc-3525-5eec-9441-609d8ee21f59','7ada2011-2720-5b69-8a9c-9291fdad70e9']::uuid[]);
insert into locations (id, case_id, name, image_url, preview_image_url, short_description, map_pos_x, map_pos_y, is_searchable, unlock_evidence_ids) values ('9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Дом Шмидтов у Горного Гиганта', null, null, 'Частный сектор под Горным Гигантом: немощёная улица, глина налипает на ботинки пудами, вдоль заборов голые яблони и поленницы. Из труб тянет угольным дымом, он стоит над крышами и не поднимается. Горы здесь совсем близко, белые от первого снега, и от них несёт холодом. Фонарей нет. Дом Шмидтов побелён, ставни голубые, на калитке табличка «Продаётся», на почтовом ящике ещё выведена от руки немецкая фамилия. Через три двора лает собака и никак не может замолчать. За соседским забором в окне шевелится занавеска.

В доме холодно и сыро. Со стен сняли ковры, на обоях остались светлые прямоугольники. В печи зола, в ведре у печи остатки угля. На кухне на стене висит телефонный аппарат, гудок есть. В полу кухни квадрат люка с железным кольцом, у люка — керосиновая лампа с закопчённым стеклом, в щелях между половицами несколько смятых окурков. Внизу, в подвале, пахнет сыростью и чем-то нежилым: старый матрас, обрезки бельевой верёвки, ведро, на матрасе серый мужской шарф. В комнате забытый чемодан с наклейкой «Hannover», стопка немецких газет и детские санки на шкафу.', 58, 80, true, array['f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba']::uuid[]);
insert into locations (id, case_id, name, image_url, preview_image_url, short_description, map_pos_x, map_pos_y, is_searchable, unlock_evidence_ids) values ('ee497c59-0b63-50e6-91fc-8c67893c99ed', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Общежитие у Зелёного базара', null, null, 'Адрес из справки адресного бюро приводит к общежитию у Зелёного базара: пятиэтажка с облупленной вывеской бывшего ПТУ, в окнах кое-где фанера вместо стёкол, на крыше спутанные антенны. С базара тянет жареным луком, мокрыми мешками и бензином, с восьми утра там кричат грузчики и скрипят тележки. На вахте бабушка в пуховом платке, радиоточка, ключи на гвоздиках. Коридор длинный, лампы горят через одну, на общей кухне на плитках кипят чайники и кто-то жарит картошку. Пахнет сырыми валенками и «Примой». Свет здесь отключают чаще, чем в центре, на подоконниках стоят огарки свечей.

У вахтёрши на столе журнал входа-выхода, разлинованный от руки. Комната на четыре койки, на одной лежит сосед и делает вид, что спит. Койка Бекенова у окна: под ней спортивная сумка и большие, разношенные ботинки, на гвозде спортивная куртка и ушанка. Если взять куртку в руки, за подкладкой нащупывается что-то плотное, завёрнутое в газету. На тумбочке кассетный магнитофон с казахской эстрадой и банка курта от матери, на стене плакат с Брюсом Ли.', 55, 33, true, array['6a92b637-cb0c-5bf4-8495-f503839bf08c']::uuid[]);
insert into locations (id, case_id, name, image_url, preview_image_url, short_description, map_pos_x, map_pos_y, is_searchable, unlock_evidence_ids) values ('a2371d56-be63-59a7-81d4-f8745d432f5d', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Квартира Фархада в микрорайоне «Орбита»', null, null, '«Орбита» на юге города: панельные девятиэтажки в ряд, пустыри между ними, разбитые дорожки, по которым к автобусной остановке тянутся люди в одинаковых пальто. Горы отсюда ближе, чем из центра, и белее. В подъезде горит лампочка, лифт поднимается со стоном, пахнет кошками и капустой. Двушка на четвёртом этаже чистая, по-вдовьи аккуратная: ковёр на стене, в серванте фарфоровый чайник с пиалами, на подоконнике в ряд пачки «Беломора». Дочери хозяина дома нет, в её комнате учебники за одиннадцатый класс, кассеты и вырезки из журналов. Обыск идёт по постановлению с санкцией прокурора. Понятые, соседи с пятого этажа, стоят в прихожей и не знают, куда деть руки.

В прихожей на расстеленной газете стоит пара зимних ботинок, недавно вымытых, с белёсыми разводами на коже. В шкафу пальто, две рубашки и костюм на плечиках; на полке над шкафом — канцелярская папка с завязками, «Дело №» без номера. На кухне под столом мешок риса, перевязанный бечёвкой, — узел завязан не по-магазинному. В ящике стола тетрадь с выручкой за лоток на Зелёном базаре. На холодильнике фотография покойной жены в чёрной рамке, рядом школьная грамота дочери. В комнате телевизор под вышитой салфеткой, на нём стопка квитанций за свет, оплаченных день в день.', 32, 82, true, array['cefb9e58-2cc4-5054-a43b-6216c7645217']::uuid[]);
update cases set start_location_id = '006a31f4-baeb-5b53-9a87-6a397ba18362' where id = '029e23c3-01e0-5d19-a0e7-3e0c2446ebab';

-- 3. Улики и показания
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('43eaf70c-177d-516a-9ab2-7aecc9633e33', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Протокол Медеуского РОВД: «грелся в машине, угорел»', 'МЕДЕУСКИЙ РОВД г. АЛМАТЫ
ПРОТОКОЛ осмотра места происшествия (выписка)
24 ноября 1996 г. Осмотр начат в 10:30, окончен в 11:40.

Место: дачный участок гр. Сартакова И., Кок-Тобе. Осмотр произведён по сообщению гр. Гринько В. (водитель), обнаружившего труп в 09:40.

В гараже — легковой автомобиль иностранного производства тёмного цвета. На водительском сиденье — труп мужчины, опознанный водителем как Сартаков И., 41 г. Ключ в замке зажигания, зажигание включено, топливный бак пуст. Ворота гаража на момент обнаружения закрыты. Явных следов насилия при наружном осмотре не обнаружено. Со слов соседей, в ночь с 23 на 24.11 в районе отключалась электроэнергия, котёл в доме не работал.

Вывод: гр. Сартаков, находясь в автомобиле с работающим двигателем в закрытом гараже с целью обогрева во время отключения электроэнергии, отравился выхлопными газами. Признаков криминального характера не усматривается.

Фототаблица на 6 л. прилагается.
Ст. оперуполномоченный, ст. лейтенант милиции (подпись неразборчива).

Резолюция: «Отказать в возбуждении уг. дела. Тело — родственникам».', null, true, null, null, true);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('e34a96b0-5d0e-5414-9ef3-048071ef84ed', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Тело Сартакова в морге: экспертиза не назначена', 'БЮРО СМЭ г. АЛМАТЫ. Журнал приёма (выписка).
24.11.96, 14:20. Сартаков И., 41 г. Доставлен из Медеуского РОВД. Основание: «для хранения до выдачи родственникам». Судебно-медицинское исследование: — (прочерк).

Поверх записи синим карандашом, наискось, рукой начальника следственного отдела ГУВД: «Кану. Вскрыть. Срочно. 25.11».

На холодном столе — тело под простынёй, бирка на щиколотке. Мужчина за сорок, ухоженные руки, щетина. Дорогие часы РОВД описал, но снять забыл. Лицо одутловатое, с синевой, в белках глаз мелкие точечные кровоизлияния. В протоколе РОВД об этом нет ни слова.', null, true, null, null, true);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('1ac01ab0-e8f1-5009-9640-d18dfa4f5e44', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Пейджер в арыке у ворот', 'Пейджер «Моторола» в чёрном кожаном чехле с клипсой. Лежал в арыке у самых ворот дачи под слоем мокрой листвы; листва над ним не потревожена. Корпус полон воды, экран мёртвый, кнопки не отвечают. На задней крышке наклейка пейджинговой компании с номером абонента.

В двух шагах — узкая калитка, щеколда задвинута, на ней висит паутина с налипшими сухими листьями. Опергруппа РОВД заходила и выходила через большие ворота.

Пейджер — у ворот. Машина — в гараже. Почему не в машине?', '29196055-161c-5b4e-a38f-352cbf3e5032', true, 'Пейджер в арыке у ворот', null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('b4e6a60f-b233-543e-b3b1-ae0a1427b6a1', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Гараж дачи: следы в слякоти, борозды, фототаблица РОВД', 'У въезда в гараж под свесом крыши слякоть сохранила два типа следов. Узкие, женские, с острым носком — под подмёрзшей коркой. Крупные, мужские, с глубоким зимним протектором — присыпаны тонким слоем снега. Там же, со стороны водительской двери, — две параллельные борозды длиной около метра, неглубокие, с рваными краями.

Фототаблица РОВД, снимки № 3 и № 4: Сартаков за рулём, голова откинута на подголовник, руки лежат на коленях ладонями вверх, левая нога подвёрнута под сиденье, а не стоит на педали. Ворот куртки поднят и застёгнут до подбородка.', '29196055-161c-5b4e-a38f-352cbf3e5032', true, 'Гараж дачи: следы в слякоти, борозды, фототаблица РОВД', null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('e4e94374-000e-52e3-bb26-9bec42b1c55b', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Китайский АОН у телефона Валентины и блокнот', 'Определитель номера китайской сборки: серая пластмассовая коробочка, красные цифры, кнопки «память» и «стоп». Поставил Игорь — «чтобы мама знала, кто звонит». Память на девяносто девять номеров; за воскресенье и понедельник набилось десятка три: больница, родня, школа, офис Игоря, соседи, телеграф. Ниже, в субботе, — один незнакомый, с первыми цифрами, какие бывают у частного сектора под горами. Время: суббота, 15:30.

Блокнот в клетку на тумбочке, карандаш на верёвочке. На открытой странице почерком учительницы:
«60» — обведено дважды.
«17:30 трамв. Ташкентская».
И тот же незнакомый номер — подчёркнут.

Валентина Петровна, проходя мимо, закрывает блокнот. Говорит, что звонков не было.', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', true, 'Китайский АОН у телефона Валентины и блокнот', null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('5cdb3307-fe10-53c5-a365-6998256b7d7a', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Конверт «на похороны» с пятью стодолларовыми купюрами', 'Белый почтовый конверт без марки, прислонён к рюмкам в серванте. Карандашом, рукой Валентины Петровны: «От Фархада — на похороны». Внутри пять купюр по сто долларов США — новые, хрусткие, «с маленькой головой».

— Фархад-ака вчера вечером принёс, — говорит Валентина Петровна, не дожидаясь вопроса. — Золотой человек. У самого ничего нет, а принёс.', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', true, 'Конверт «на похороны» с пятью стодолларовыми купюрами', null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('abc6fac8-abbd-5589-b6b5-958cd368e7fe', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Фархад: перевязанная кисть', 'Из рабочих заметок следователя.

Мамаджанов Фархад, 49 лет. Левая кисть перевязана свежим бинтом, от запястья до костяшек; повязка аккуратная, намотана своими руками. На вопрос отмахивается: «Казан. Плов делал, обжёгся. Ерунда, заживёт».', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('4cc34317-760f-577c-b05f-e0374aee4f23', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Журнал КПП базы: «Мамаджанов Ф., 16:10–16:40»', 'ЖУРНАЛ учёта посетителей и автотранспорта. КПП № 1.

(Страница за конец октября, выписка.)
28.10.96 | 09:15 | «КамАЗ» 45-17 | выгрузка, склад 3 | (подпись)
28.10.96 | 11:40 | Есенова Г. | в бухгалтерию | (подпись)
28.10.96 | 14:05 | «ГАЗель» | экспедитор Ли | (подпись)
28.10.96 | 16:10–16:40 | Мамаджанов Ф. | к Сартакову И. | пешком | (подпись)
28.10.96 | 17:20 | ЗИЛ | вывоз тары | (подпись)

(Последняя заполненная страница, выписка.)
23.11.96 | 11:30 | ЗИЛ | вывоз тары | (подпись)
23.11.96 | 17:55–19:10 | Ахметов Д. | ВАЗ-2109, белая | (подпись)
23.11.96 | 20:00 | заступил на смену Нуртазин Е. | (подпись)

Обычные строчки среди сотен таких же. Почерк дневного дежурного ровный, графа «цель визита» у Мамаджанова заполнена просто: «к Сартакову И.».', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', true, 'Журнал КПП базы: «Мамаджанов Ф., 16:10–16:40»', null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('4f67be3f-f5f7-5ab5-bb69-611053df3042', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Ксерокопии всех купюр выкупа из стола Данияра', 'Пачка листов формата А4, ещё пахнущих тонером. На каждом листе по восемь стодолларовых купюр, лицевой стороной, — серия и номер читаются без лупы. Листы пронумерованы карандашом в правом верхнем углу. На последнем, внизу, мелким аккуратным почерком: «23.11.96, 10:15. Итого 40 000. Д. А.».

Лежали в нижнем ящике стола Ахметова под папкой «Договоры поставки — 1995».', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('be5c249c-d25f-5239-865f-5aef2088bc61', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Пейджер охранного агентства на поясе Ерлана', 'Пейджер на клипсе, на ремне Нуртазина, корпус потёрт, на обороте наклейка охранного агентства и номер абонента пейджинговой компании. Память сообщений пуста — всё стёрто.

Когда вы просите показать пейджер, Ерлан долго возится с клипсой, роняет его на пол и говорит, не глядя: «Да там ничего нету, служебное всё».', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', true, 'Пейджер охранного агентства на поясе Ерлана', null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('c2c5ba62-e24e-523f-93bc-d8909b28e717', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Подвал Шмидтов: матрас, верёвки, шарф, люк, лампа, окурки', 'Протокол осмотра (выписка). Эксперт-криминалист Сеитова Г.

Люк в полу кухни, деревянная крышка с железным кольцом, ведёт в подвал глубиной около двух метров, спуск по приставной лестнице. В подвале ватный матрас, ветхий; обрезки бельевой верёвки, узлы затянуты; эмалированное ведро. На матрасе мужской шарф серого цвета, кашемировый, импортный. По описанию гр. Сартаковой В. П. это шарф её сына.

На кухне у люка керосиновая лампа «летучая мышь» с закопчённым стеклом. С лампы и крышки люка изъяты следы пальцев рук. В щелях пола у люка шесть окурков папирос, гильзы смяты «гармошкой», как мнут «Беломор».', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', true, 'Подвал Шмидтов: матрас, верёвки, шарф, люк, лампа, окурки', null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('46e78eb0-d057-5e5d-8a00-81457f8f3d20', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Вещи Олжаса: $3000 в куртке, куртка, ушанка, ботинки 45 размера', 'Протокол осмотра (выписка). Общежитие у Зелёного базара, комната 412, койка Бекенова О.

Куртка спортивная, синяя, с белыми полосами на рукавах, импортная. За подкладкой свёрток в газете «Вечерний Алматы»: тридцать купюр по 100 долларов США. Шапка-ушанка из искусственного меха, чёрная. Ботинки мужские зимние, 45 размер, протектор стёрт до гладкого на носке.

Сосед по комнате, отвернувшись к стене: «Он на мать копил. Говорил так».', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', true, 'Вещи Олжаса: $3000 в куртке, куртка, ушанка, ботинки 45 размера', null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('ed68230f-dcda-56e7-a77c-ecd7a4cc05a4', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Журнал вахтёрши: Бекенов в субботу с 19:30 до утра в общежитии', 'ЖУРНАЛ входа-выхода проживающих (выписка).

23.11.96 (суббота)
19:30 — Бекенов О., к. 412 — вход.
(Записей о выходе Бекенова О. за 23.11 нет.)
24.11.96 (воскресенье)
08:50 — Бекенов О., к. 412 — выход.
Подпись вахтёра.

Вахтёрша, Роза-апа: — Пришёл в полвосьмого, мокрый весь, и сразу наверх. Не выходил, у меня дверь на замке с одиннадцати, ключ вот он. Ребята в комнате скажут, они в карты до ночи играли, а он лежал лицом к стене.', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', true, 'Журнал вахтёрши: Бекенов в субботу с 19:30 до утра в общежитии', null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('00b31a8e-e1ee-5474-a323-177b43b153d3', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Зимние ботинки 43 размера с порезом на каблуке', 'Протокол обыска (выписка). Квартира Мамаджанова Ф., мкр «Орбита».

В прихожей на расстеленной газете — ботинки мужские зимние, кожаные, чёрные, 43 размер. На каблуке одного ботинка косой порез длиной около 1 см. Ботинки недавно вымыты, кожа в белёсых разводах, в шве у подошвы остатки грязи. Других зимних ботинок в квартире не обнаружено: в шкафу только летние туфли и домашние тапки.', 'a2371d56-be63-59a7-81d4-f8745d432f5d', true, 'Зимние ботинки 43 размера с порезом на каблуке', null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('b322dfba-0cb0-52bc-9610-328a905bc004', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Расписка кредитора на бланке купонного инвестиционного фонда', 'Среди бумаг из пакета — лист, сложенный вчетверо. Сверху типографская шапка купонного инвестиционного приватизационного фонда: название, номер лицензии, адрес; круглая печать фонда в углу смазана.

Ниже от руки, синей пастой:
«Я, нижеподписавшийся, получил от Мамаджанова Ф. доллары США в счёт долга и процентов по нему. Претензий по сроку не имею. 24.11.96».
Сумма вписана цифрами и дважды исправлена. Подпись размашистая, с завитком, расшифровки нет.

На обороте карандашом, другим почерком, столбик цифр, перечёркнутый.', 'a2371d56-be63-59a7-81d4-f8745d432f5d', true, 'Расписка кредитора на бланке купонного инвестиционного фонда', '[["2d1a03f4-be7f-5007-8fe1-71c12d498c29"]]'::jsonb, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('2d1a03f4-be7f-5007-8fe1-71c12d498c29', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Тайник в мешке с рисом: доллары и расписки; доверенность Шмидтов в папке на полке', 'Протокол обыска (выписка).

1. Под столом на кухне мешок риса, около 25 кг, перевязан бечёвкой. В глубине мешка полиэтиленовый пакет, в нём:
— доллары США купюрами по 100, пачками в банковских резинках;
— расписки гр. Мамаджанова Ф. в получении денег в долг, несколько листов, суммы в долларах «под проценты», даты — лето и осень 1996 г.

2. В комнате, на полке над шкафом, канцелярская папка с завязками, не спрятана. В ней бумаги по продаже дома, среди них нотариальная доверенность: гр. Шмидт Г. уполномочивает гр. Мамаджанова Фархада продать принадлежащий ему жилой дом в частном секторе у Горного Гиганта, а до продажи распоряжаться им и пользоваться.

Рис из мешка высыпан на газеты, понятые смотрят на него, а не на деньги.', 'a2371d56-be63-59a7-81d4-f8745d432f5d', true, 'Тайник в мешке с рисом: доллары и расписки; доверенность Шмидтов в папке на полке', null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('54bf13bc-3525-5eec-9441-609d8ee21f59', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Заключение СМЭ: удушение, не угар', 'Заключение СМЭ: удушение, не угар; следы связывания; под ногтями чужая кровь.

АКТ судебно-медицинского исследования трупа Сартакова И., 41 г. (выводы).
1. Смерть наступила в субботу 23.11.96 около 22:00 от механической асфиксии вследствие сдавления шеи: лицо одутловатое, синюшное, точечные кровоизлияния в соединительных оболочках глаз.
2. Признаков отравления окисью углерода не обнаружено. В автомобиль помещён после наступления смерти.
3. На запястьях слабо выраженные следы сдавления, характерные для связывания поверх одежды. Щетина около двух суток, признаки обезвоживания и голодания: не менее двух суток до смерти находился вне обычных условий.
4. Под ногтевыми пластинами обеих рук — следы крови группы II. Группа крови покойного — I.
Судмедэксперт Кан Ю. Н. 25.11.96.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('7ada2011-2720-5b69-8a9c-9291fdad70e9', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Пейджер Игоря: последний сигнал в четверг', 'Пейджер Игоря: с вечера четверга ничего не принял, на сообщения никто не перезвонил.

Справка эксперта-криминалиста Сеитовой Г.: пейджер, изъятый из арыка у ворот дачи, после просушки и замены элемента питания включился. Последнее принятое сообщение в памяти аппарата — 21.11.96 (четверг), 17:35. Принятых позже сообщений нет.
Справка ИВЦ (Абишев Р.): по журналу пейджинговой компании с вечера 21.11 по 23.11 на номер Сартакова передавались сообщения из офиса фирмы («СРОЧНО ПЕРЕЗВОНИ») и от Сартаковой В. П. В офисе подтверждают: ответного звонка не было. Пейджер односторонний, факт прочтения оператор не фиксирует.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('60950128-af31-513e-b8de-bb87b02332cc', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Трасология: следы у гаража', 'Трасология у гаража: мужские следы ночные, женские — дневные, раньше.

Заключение эксперта-криминалиста Сеитовой Г. (выводы).
1. Следы мужской зимней обуви, 43 размер, на каблуке косой порез около 1 см. Покрыты тонким слоем снега, выпавшего около 01:00 в воскресенье, — оставлены ночью, до снегопада.
2. Следы женской обуви, 37 размер. Находятся под подмёрзшей коркой слякоти — оставлены раньше, засветло.
3. Две параллельные борозды со стороны водительской двери — следы волочения: тело несли, ноги волочились.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('c4c95f03-86b0-5820-b9f4-736453e2dbef', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Виктор: «по четвергам он ездил один»', 'Виктор: по четвергам Игорь ездил на дачу один; у базы стояла «Волга» с одной фарой.

Из объяснения Гринько В.: по четвергам в 17:00 Сартаков отпускал водителя и один уезжал на дачу; привычка появилась после развода, о ней знали в офисе и на КПП. В четверг за неделю до смерти у ворот базы стояла белая «Волга» ГАЗ-24 с разбитой левой фарой; водитель курил и смотрел на ворота. Номер не запомнил. Водителя не знает.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('0a295d5f-e115-5c89-a26a-5992761304a0', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Виктор: ссора Игоря с Данияром', 'Виктор: Игорь кричал на Данияра «Месяц тебе, или сядешь».

Из объяснения Гринько В.: в субботу 16.11, за пять дней до пропажи Сартакова, находясь в приёмной, слышал, как Сартаков кричал в кабинете на Ахметова: «Месяц тебе, или сядешь». Ахметов вышел бледный. О чём речь, не знает.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('42ea83ef-f3ad-504f-99e0-da4ecb9fe57d', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Алия: в пятницу гараж был пуст', 'Алия: в пятницу в 15:00 гараж был пуст; в субботу она была на дежурстве.

Из объяснения Жумабаевой (Сартаковой) А.: в пятницу 22.11 около 15:00 открыла ворота и дом дачи своими старыми ключами (на одной связке) и забрала папку документов о приватизации дачи для адвоката. Гараж был пуст, машины не было. В субботу с 20:00 до 08:00 находилась на ночном дежурстве в городской больнице, в 23:10 давала наркоз при экстренной операции (журнал дежурств, протокол операции с её подписью).', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('b170d031-ba6c-5e70-829f-cbd96f761931', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Признание Валентины: похищение и выкуп', 'Валентина признаётся: похищение, звонки, тайный выкуп.

Из протокола допроса свидетеля Сартаковой В. П.: в четверг 21.11 около 21:00 позвонили из таксофона, потребовали $60 000, пригрозили внучке, если семья обратится в милицию. В милицию не обращалась; водителю Гринько сказала, что сын уехал в Бишкек. Вместе с Ахметовым Д. собрала $40 000. В субботу в 15:30 позвонили снова и назвали место — номер сохранился в памяти АОН. В субботу с 19:30 до 01:30 Ахметов находился у неё, ждали звонка, что Игоря отпустили.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('6d8d58c7-784b-5d25-9f9e-d6c55f6966ba', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Фархад: «сидел при свечке»', 'Фархад среди пришедших с соболезнованием: «давно помирились»; в субботу «сидел при свечке».

Со слов Мамаджанова Ф.: с Игорем давно помирились, зла не держал. В субботу вечером сидел дома в микрорайоне «Орбита» один — дочь Зарина с четверга у родни в Ташкенте; «у нас свет отключили», сидел при свечке, никуда не выходил.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('ea60506a-dfdb-5176-a63a-2fd3c47f8b6e', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Признание Данияра: выкуп и копии купюр', 'Данияр признаётся: выкуп из «чёрной» кассы, курьер на остановке, алиби.

Из протокола допроса Ахметова Д.: о похищении знал с пятницы; по просьбе Сартаковой В. П. в милицию не обращался. $40 000 взял из неучтённой кассы фирмы и вернул туда ранее выведенные им средства. Перед передачей снял ксерокопии всех купюр. В субботу в 17:30 оставил пакет под скамейкой на трамвайной остановке на Ташкентской; в темноте видел только высокого молодого парня в спортивной куртке и ушанке, лица не разглядел. Оттуда в 17:55 заехал на базу, убрал ксерокопии в свой стол, в 19:10 выехал (журнал КПП). В 15:30, во время второго звонка, находился у Сартаковой В. П. и сам видел номер на АОН; оттуда с пакетом поехал на остановку. В 19:30 вернулся к Сартаковой и находился у неё до 01:30.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('009a36f7-b362-586d-8943-61cd46149c3c', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Данияр: «Я тебя садиться не просил»', 'Данияр: в октябре Игорь отказал Фархаду в доле и унизил его.

Из протокола допроса Ахметова Д.: 28.10.96 Мамаджанов Ф. пришёл на базу просить свою долю. Сартаков при Ахметове ответил: «Я тебя садиться не просил. Хочешь — иди завскладом». Мамаджанов ушёл молча. В 1994 г. Мамаджанов был осуждён за товар их общей фирмы, взяв вину на себя, отбыл полтора года.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('9eedb06d-09c9-5fa6-b91f-46d7753f78b4', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Справка электросетей: Кок-Тобе', 'Справка электросетей: район Кок-Тобе в субботу обесточен с 19:00 до 02:00.

ДИСПЕТЧЕРСКАЯ СЛУЖБА РАЙОННЫХ ЭЛЕКТРОСЕТЕЙ. Справка по запросу ГУВД о районе Кок-Тобе.
23.11.96 с 19:00 до 02:00 24.11.96 потребители района Кок-Тобе отключены по графику ограничения потребления.
Диспетчер (подпись), печать.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('64b699fc-69d6-5bc3-ab81-b5a48df561bd', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Справка электросетей: «Орбита»', 'Справка электросетей: в «Орбите» ни в пятницу, ни в субботу свет не отключали.

ДИСПЕТЧЕРСКАЯ СЛУЖБА РАЙОННЫХ ЭЛЕКТРОСЕТЕЙ. Справка по отдельному запросу ГУВД.
В микрорайоне «Орбита» 22.11.96 и 23.11.96 плановых и аварийных отключений потребителей не производилось.
23.11.96 с 19:00 до 02:00 24.11.96 по графику ограничения отключались потребители районов Кок-Тобе и Горный Гигант.
Диспетчер (подпись), печать.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Адресное бюро: телефон Шмидта', 'Адресное бюро: номер из АОН — телефон Шмидта Г., выбывшего в ФРГ.

Справка ИВЦ (Абишев Р.): номер телефона, зафиксированный в памяти АОН в субботу в 15:30, зарегистрирован на гр. Шмидта Г. Абонент выбыл на постоянное жительство в ФРГ. Адрес — частный сектор у Горного Гиганта. Со слов участкового, дом пустует и продаётся по доверенности. Телефон не отключён.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('27ae146a-a05c-5e7a-84a1-899c35e883e4', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Дактилоскопия: пальцы на люке и лампе', 'Дактилоскопия: пальцы на люке и лампе — Мамаджанова Ф.; его группа — II.

Справка ИВЦ (Абишев Р.) по результатам ручного сравнения с картотекой.
1. Следы пальцев рук с крышки люка подвала и с керосиновой лампы в доме Шмидта совпадают с дактокартой Мамаджанова Фархада (судим в 1994 г., таможенное дело).
2. Второй набор следов с крышки люка в картотеке не значится (лицо, не имеющее судимости).
3. В учётном деле Мамаджанова — медицинская карта из колонии: группа крови II.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('f725c4c5-f254-5c01-b718-3531a957102a', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Показания Тамары Шнайдер', 'Тамара: «Волга» Фархада у дома Шмидтов с 18:15 до ночи; покупателей не было; иномарка уехала без фар.

Из протокола допроса свидетеля Шнайдер Т. Ф.: дом Шмидтов продаёт Мамаджанов Фархад, он водил покупателей, свидетель знает его в лицо; в среду он сказал ей, что «скоро въедут люди». В пятницу из трубы пустого дома шёл дым, под навесом стояла тёмная иномарка, печь топил высокий молодой парень. В субботу около 18:15 в свете единственной фары подъехала белая «Волга», из неё вышли Мамаджанов и высокий молодой парень; парень вскоре ушёл пешком. Больше в тот вечер никто не приезжал, покупателей не было. После отключения света на тёмной улице до ночи светилось только окно Шмидтов — керосиновая лампа. Около 23:20 со двора выехала иномарка с выключенными фарами (свидетель узнала её по звуку мотора). «Волга» простояла у калитки примерно до 01:30 и уехала по свежему снегу.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('c50332f2-fb14-5cff-9ea2-9581024ac2e3', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Журнал пейджинга: «ЧЕТВЕРГ В СИЛЕ? Ф.»', 'Журнал пейджинговой компании: «ЧЕТВЕРГ В СИЛЕ? Ф.» на пейджер Ерлана.

Выписка из журнала операторов пейджинговой компании (по запросу ГУВД):
21.11.96, 16:30. Абонент: Нуртазин Е. Текст сообщения: «ЧЕТВЕРГ В СИЛЕ? Ф.».
Оператор (подпись).', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('b229ab87-5e5b-5f61-8a7b-18c17718e4cf', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Признание Ерлана', 'Ерлан признаётся: продал Фархаду «четверги» за списанный долг.

Из протокола допроса Нуртазина Е.: в 1993 г. Мамаджанов Ф. дал ему $1500 на операцию матери, долг не был возвращён. В субботу 09.11, за две недели до пропажи Сартакова, в чайхане у Зелёного базара Мамаджанов предложил списать долг, если Нуртазин скажет, когда Сартаков ездит без водителя, — «поговорить по-мужски». Нуртазин сообщил про четверги; в четверг 21.11 получил сообщение на пейджер и подтвердил по телефону. О похищении не знал. В субботу с 20:00 до 08:00 находился на смене, ежечасно отзванивался на пульт агентства.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('3b4003bd-1d82-5ec7-b07b-4c54af3ac4c0', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Профиль Бейсенова: похититель знаком жертве', 'Криминолог: заложника убивают после выкупа, когда боятся опознания.

Из консультации доцента Бейсенова А.: в типичном случае заложника после получения выкупа отпускают; убивают, как правило, когда похититель боится опознания — то есть жертва его знала. Инсценировку выполнил человек, знавший дачу и привычки Сартакова и рассчитывавший на молчание семьи. Круг: друзья семьи, партнёры, бывшие супруги, охрана.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('d91852b9-daca-5340-80c9-a13cffe680cc', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Деньги Олжаса — из выкупа', 'Сравнение купюр: $3000 Бекенова — из выкупа.

Протокол сравнения (Сеитова Г.): номера и серии тридцати купюр по $100, изъятых у Бекенова О., полностью совпадают с номерами на ксерокопиях купюр выкупа, переданных Ахметовым Д.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('0146fe89-1029-5d65-87bb-f750dfe7ad2d', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Признание Олжаса: похищение', 'Олжас признаётся в похищении — и твердит, что «аке ни при чём».

Из протокола допроса подозреваемого Бекенова О.: в четверг вечером схватил Сартакова у ворот дачи; перегнал его машину во двор дома Шмидтов (водить умеет, прав не имеет); удерживал Сартакова в подвале; звонил Сартаковой В. П. из таксофонов, в субботу — с телефона в доме Шмидтов, так как таксофон на остановке был сломан; в субботу забрал пакет с деньгами на остановке. Утверждает, что действовал один: «Аке ни при чём, я сам всё придумал». Считает, что утром Сартакова отпустили, тот уехал на своей машине на дачу и умер сам, от угара.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Очная ставка: «Я тебя узнал»', 'Очная ставка: Олжас передал Фархаду «я тебя узнал» — и был отослан.

Из протокола очной ставки Бекенова О. и Мамаджанова Ф. (кабинет следователя ГУВД): узнав, что Сартаков задушен около 22:00, а остаток выкупа обнаружен у Мамаджанова, Бекенов показал: с остановки к дому Шмидтов приехали вдвоём с Мамаджановым, кроме них в доме был только Сартаков. Около 18:15 передал Мамаджанову слова Сартакова: «Фархад, я тебя узнал. Бери деньги и отпусти, никому не скажу». По словам Бекенова, Сартаков узнал Мамаджанова через мешок на голове — по кашлю и запаху «Беломора». Около 18:45 Мамаджанов отправил его в общежитие, сказав, что утром отпустит Сартакова за городом.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('6fc41a46-a0eb-5890-9b26-3b19bcef490d', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Трасология: ботинки с порезом', 'Трасология: ботинки Мамаджанова оставили мужские следы у гаража.

Заключение эксперта Сеитовой Г.: следы мужской обуви у гаража дачи на Кок-Тобе оставлены ботинками, изъятыми при обыске в квартире Мамаджанова Ф. (размер, протектор, порез на каблуке).', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('107fcb2c-e909-5f81-bba4-d218265227c5', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Доллары из тайника — из выкупа', 'Сравнение купюр: доллары из тайника Фархада — из выкупа.

Протокол сравнения (Сеитова Г.): номера и серии всех купюр, изъятых из мешка с рисом в квартире Мамаджанова Ф., совпадают с ксерокопиями купюр выкупа.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Освидетельствование: царапины от ногтей', 'Освидетельствование: под повязкой — царапины от ногтей, ожога нет; группа II.

Протокол освидетельствования задержанного Мамаджанова Ф. при понятых, заключение судмедэксперта Кана Ю. Н.: на тыльной стороне левой кисти под повязкой — три параллельные царапины, причинённые ногтями человека; давность четверо-шестеро суток, в стадии заживления, причинение вечером 23.11 не исключается. Следов ожога нет. Характерных следов когтей животного нет. Группа крови Мамаджанова — II (медкарта колонии), совпадает с группой крови под ногтями Сартакова.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('26a10711-a53c-5105-9ed4-190697869496', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Купюры из конверта — из выкупа', 'Сравнение купюр: конверт «на похороны» — из выкупа.

Протокол сравнения (Сеитова Г.): номера пяти купюр по $100 из конверта, переданного Мамаджановым Ф. гр. Сартаковой В. П., совпадают с ксерокопиями купюр выкупа.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('b177dd97-7391-5f5e-8308-72a1073516c2', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Группы крови подозреваемых', 'Группы крови фигурантов: II — у двоих из четверых.

Справка (Кан Ю. Н.) по медкартам и учётным делам:
Мамаджанов Ф. — II (медкарта колонии);
Ахметов Д. — II;
Нуртазин Е. — I (личное дело МВД);
Жумабаева А. — III.
Под ногтями Сартакова — II.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('7a9bdd9a-4323-5342-a3bd-24301a6d6e88', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Трасология: обувь подозреваемых', 'Трасология: обувь проверенных фигурантов не совпадает со следами у гаража.

Заключение эксперта Сеитовой Г.:
Нуртазин Е. — форменные ботинки, 43 размер, протектор другого рисунка;
Ахметов Д. — изъята вся обувь 43 размера: импортные туфли с гладкой подошвой и зимние ботинки с протектором иного рисунка, без пореза;
Жумабаева А. — 37 размер.
Ни одна из изъятых пар мужских следов у гаража не оставила.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('d8f33493-fc81-5e50-af40-37d9500040b6', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'ИЦ/ГАИ: машины подозреваемых', 'ИЦ/ГАИ: машины фигурантов — белые только у двоих.

Справка ИВЦ (Абишев Р.):
Мамаджанов Ф. — ГАЗ-24 «Волга», белая;
Ахметов Д. — ВАЗ-2109, белая (при осмотре фары целы);
Жумабаева А. — ЗАЗ «Таврия», красная;
Нуртазин Е. — личного транспорта нет, пользуется служебным УАЗ агентства.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Признание Фархада', 'Признание Фархада: решил убить, когда узнал, что Игорь его узнал.

Из протокола допроса обвиняемого Мамаджанова Ф.: Нуртазину списал долг за сведения о четвергах. Бекенову сказал, что никто не пострадает. Решение убить принял, когда Бекенов передал, что Сартаков его узнал. Задушил его один, отвёз тело на машине Сартакова на Кок-Тобе, оставил с работающим двигателем. С Кок-Тобе спустился пешком, внизу остановил частника, номер машины не помнит. Часть денег отдал кредитору.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('cefb9e58-2cc4-5054-a43b-6216c7645217', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Санкция прокурора на задержание', 'Санкция прокурора: задержание Мамаджанова Ф. и обыск в его квартире в «Орбите».

ПОСТАНОВЛЕНИЕ о задержании подозреваемого и производстве обыска (выписка).
Задержать Мамаджанова Фархада в порядке, предусмотренном УПК. Произвести обыск по месту его жительства: г. Алматы, мкр «Орбита».
В углу листа фиолетовыми чернилами: «Санкционирую». Прокурор (подпись), гербовая печать.

Начальник отдела ставит свою подпись под прокурорской, не садясь.
— Две независимые бумаги на одного человека. Прокурору хватило, мне тоже. Бери понятых, бери Сеитову. Его — сюда, в кабинет. И без самодеятельности: человек никуда не бегал, значит, уверен в себе. Таких берут вежливо.', null, true, null, '[["27ae146a-a05c-5e7a-84a1-899c35e883e4", "f725c4c5-f254-5c01-b718-3531a957102a"], ["27ae146a-a05c-5e7a-84a1-899c35e883e4", "26a10711-a53c-5105-9ed4-190697869496"], ["f725c4c5-f254-5c01-b718-3531a957102a", "26a10711-a53c-5105-9ed4-190697869496"]]'::jsonb, true);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('6a92b637-cb0c-5bf4-8495-f503839bf08c', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Адресное бюро: племянник Мамаджанова', 'Адресное бюро: племянник Мамаджанова — Бекенов Олжас, общежитие у Зелёного базара.

Справка ИВЦ (Абишев Р.): в учётном деле Мамаджанова Ф. (1994 г.), в анкете, в графе «родственники» указана двоюродная сестра — Бекенова, Талгарский район. По данным адресного бюро в г. Алматы временно прописан Бекенов Олжас, 22 года, уроженец Талгарского района: общежитие у Зелёного базара, комната 412.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('9281d556-d163-5537-a0e2-e4cd2e635ba5', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Экспертизы по Бекенову и Ахметову', 'Экспертизы по задержанному Бекенову: второй набор пальцев — его; царапин нет ни у него, ни у Ахметова.

Сводная справка (Сеитова Г., Кан Ю. Н., Абишев Р.):
1. Второй набор следов пальцев с крышки люка подвала Шмидтов оставлен Бекеновым О. С отпечатками Ахметова Д. (дактилоскопирован добровольно) не совпадает.
2. Группа крови Бекенова О. — II.
3. Кисти рук Бекенова О. и Ахметова Д. осмотрены: свежих повреждений нет.
4. По данным ГАИ водительского удостоверения и транспорта у Бекенова О. нет; со слов Бекенова, водить умеет.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('4e8b269e-8c91-5629-b60d-13930fa7e61e', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Зоя Михайловна: «девятка» до ночи', 'Соседка Зоя Михайловна: «девятка» Данияра под окном до ночи, около 22:00 он курил на лестнице.

Из объяснения Лукиной З. М. (соседка Сартаковой В. П. по лестничной площадке): белая ВАЗ-2109 Ахметова стояла под окнами дома с вечера субботы 23.11 до глубокой ночи. Около 22:00, «перед вторым „Временем“», Ахметов курил на лестничной площадке; свидетель вышла на запах дыма и сделала ему замечание. Окурки импортных сигарет — в банке у мусоропровода.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('06da149b-c92c-54fa-a5f5-b78ff87dbc92', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Хронология против версии о Данияре', 'Хронология: подготовка похищения старше ссоры Игоря с Данияром.

Сводная таблица дат по материалам дела:
09.11 (сб) — разговор в чайхане у Зелёного базара: наводчику предложено списать долг за сведения о четвергах (показания Нуртазина);
14.11 (чт) — белая «Волга» с разбитой левой фарой у ворот базы (показания Гринько);
16.11 (сб) — Сартаков уличает Ахметова в выводе денег: «Месяц тебе, или сядешь» (показания Гринько);
21.11 (чт) — похищение.
Наводка и наблюдение за базой начаты раньше, чем у Ахметова возник конфликт с Сартаковым.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('7188cb7d-2261-5a9c-8f78-e603caa6b31a', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Фархад: «показывал дом покупателю»', 'Запасная версия Фархада: «показывал дом покупателю».

Со слов задержанного Мамаджанова Ф.: в субботу вечером заезжал в дом Шмидтов, показывал дом покупателю; сидели с керосиновой лампой, так как света не было; покупатель уехал, затем уехал и он. Про свечку дома «перепутал»: свет в «Орбите», по его словам, отключали в пятницу. Имени покупателя не называет.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('3772cdd6-1fe9-52d0-a268-3f82441220c7', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Осмотр машины Игоря: глина и чистый руль', 'Машина Игоря на стоянке РОВД: глина в колёсных арках, на руле ни одного отпечатка.

Справка эксперта-криминалиста Сеитовой Г. по осмотру автомобиля Сартакова на стоянке Медеуского РОВД: в колёсных арках налёт жёлтой глины, характерной для немощёных улиц частного сектора (такие, в частности, у Горного Гиганта); подъезд к даче на Кок-Тобе — асфальт и щебень. На рулевом колесе следов пальцев рук не выявлено, в том числе следов владельца: последним автомобилем управлял человек в перчатках.', null, true, null, null, false);
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant) values ('e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Валентина: расцарапанная рука Фархада', 'Валентина о Фархаде: конверт, расцарапанная рука, «Береги Дашу».

Из протокола дополнительного допроса свидетеля Сартаковой В. П.: в воскресенье 24.11 вечером Мамаджанов Ф. принёс конверт с деньгами «на похороны». На левой кисти у него были свежие царапины; на её вопрос ответил: «Собака на базаре». Уходя, в прихожей, наедине, сказал ей: «Бандиты сейчас такие, Валентина-апа. Береги Дашу, никому ни слова». Тогда она приняла это за заботу.', null, true, null, null, false);

-- 4. Персонажи
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, is_expert, is_suspect, is_case_subject) values ('57949d2d-0b2d-5c04-812c-5849e9441857', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '006a31f4-baeb-5b53-9a87-6a397ba18362', 'Начальник следственного отдела', 'ГУВД г. Алматы', 'Понедельник, 25 ноября 1996 года, 9:10. Кабинет начальника следственного отдела ГУВД г. Алматы.

— Садись. Пальто не снимай, батарея всё равно не греет. Вот тебе подарок из Медеуского РОВД — отказной материал. Сартаков Игорь, сорок один год, хозяин базы на Ташкентской, импорт оборудования. Вчера в 09:40 водитель Гринько нашёл его в гараже собственной дачи на Кок-Тобе: за рулём, ключ в зажигании, бак сухой, ворота гаража закрыты. В субботу вечером на Кок-Тобе отключали свет. Грелся в машине, задремал, угорел. Опергруппа управилась за час, вскрытие не назначили — «и так ясно». Мать хочет хоронить, РОВД хочет закрыть, прокуратура хочет, чтобы я подписал.

А я не подпишу, пока ты не посмотришь. Мужик при деньгах, в разводе, база приватизированная — такие у нас сами редко умирают. Тело в морге, Юрий Николаевич Кан ждёт бумагу. Гульнара Сеитова съездит с тобой на дачу, Ринат Абишев посидит на картотеках, доцент Бейсенов из высшей школы МВД на этой неделе у нас консультирует. Даю неделю. Угорел — закроем с чистой совестью. Нет — найди мне, как он оказался за рулём.', '[{"q": "Кто мне поможет?", "a": "Сеитова — следы и вещдоки. Абишев — картотеки, адресное бюро, запросы на узел связи и в электросети. Кан — вскрытие. Бейсенов — профиль, если понадобится. Они все в здании, иди к ним сразу."}, {"q": "Что не так с этим «угаром»?", "a": "Может, и ничего. Но вскрытия не было, а мне на подпись несут отказной. Начни с морга — Кан ждёт бумагу. И съезди на дачу, пока снег всё не замёл."}]'::jsonb, false, false, false);
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url, specialization) values ('d3ddcd6d-4093-5464-970c-de4ad3cb9af1', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '006a31f4-baeb-5b53-9a87-6a397ba18362', 'Гульнара Сеитова', 'Криминалист ЭКО', 'Гульнара Сеитова, эксперт-криминалист ЭКО. Свитер под белым халатом, волосы стянуты в тугой узел, в руках линейка и калька. Здоровается кивком.
— Что смотреть? Говорите конкретно.', '[{"q": "Что вы можете сделать по этому делу?", "a": "— Осмотр, трасология, следы рук, сравнение предметов. Купюры по номерам тоже могу, если будет с чем сравнивать. Результат в тот же день, если не надо гонять по картотеке. Картотека — это к Абишеву."}, {"q": "Как по-вашему, это несчастный случай?", "a": "— По-моему — ничего. Привезите мне предмет, и я скажу, что на нём есть. А «по-моему» пусть говорит начальство."}]'::jsonb, '{"b4e6a60f-b233-543e-b3b1-ae0a1427b6a1": "Сеитова раскладывает на капоте служебного «уазика» кальку и линейку.\n— Два типа следов. Первый: мужская зимняя обувь, сорок третий размер, протектор глубокий, на каблуке косой порез, около сантиметра. Лежат под тонким слоем снега. Снег здесь, по метеостанции, пошёл около часа ночи на воскресенье. Значит, следы ночные, до часа. Второй: женская обувь, тридцать седьмой. Эти под подмёрзшей коркой слякоти, оставлены раньше, засветло, пока грязь была мягкой. Борозды: две, параллельные, со стороны водительской двери. Так волочатся каблуки. Тело несли, ноги тащились по земле. Чьё — не скажу. Скажу размер.", "46e78eb0-d057-5e5d-8a00-81457f8f3d20": "— Три тысячи. Тридцать купюр по сто. — Сеитова не поднимает головы от стола. — Сверила с ксерокопиями: серия, номер, у двух купюр надрыв на краю, на копии он тоже виден. Все тридцать есть в копиях выкупа. Совпадение полное. Протокол сравнения подпишу сегодня. Как они попали к нему за подкладку — не моя графа.", "00b31a8e-e1ee-5474-a323-177b43b153d3": "— Сорок третий. Протектор тот же. Порез на каблуке косой, около сантиметра, края совпадают со слепком у гаража. Ботинки мыли, но в шве у подошвы грязь осталась, на экспертизу хватит. Подошву сравнила с калькой по шести точкам, все шесть совпали. — Сеитова снимает перчатки. — Эти ботинки оставили мужские следы у гаража дачи. Чьи ноги были в ботинках — вопрос не ко мне.", "2d1a03f4-be7f-5007-8fe1-71c12d498c29": "— Доллары из мешка с рисом. — Сеитова кладёт на стол стопку протоколов и придвигает к ней листы ксерокопий. — Пересчитала при понятых, переписала номера, сверила с копиями Ахметова лист за листом. Каждая купюра из тайника есть в копиях выкупа. Ни одной лишней, ни одной чужой. Резинки банковские, описаны. Рис описан отдельно, если вам интересно.", "4f67be3f-f5f7-5ab5-bb69-611053df3042": "Вы кладёте рядом с конвертом «на похороны» показания Шнайдер: тот, кто принёс конверт, в субботу вечером был у дома Шмидтов.\n— Конверт от матери покойного. Пять купюр по сто, новые, «с маленькой головой». — Сеитова раскладывает купюры рядом с листами ксерокопий. — Сверила номера. Все пять есть в копиях выкупа. Совпадение полное. Надпись карандашом «От Фархада — на похороны» внесена в протокол. Больше по конверту ничего.", "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44": "Сеитова вскрывает корпус пейджера над лотком, сливает мутную воду и оставляет плату сохнуть на чуть тёплой батарее. Наутро ставит новый элемент питания.\n— Включился. — Она поворачивает к вам экран с бледными цифрами. — Последнее принятое сообщение в памяти: четверг, двадцать первое, семнадцать тридцать пять. Позже — ничего. В воде аппарат не принимает. Что на него слали после, знает оператор, это к Абишеву. Калитку я сфотографировала. Выводов по ней не делаю.", "60950128-af31-513e-b8de-bb87b02332cc": "— Обувь. — Сеитова раскладывает кальки веером. — Нуртазин: форменные ботинки, сорок третий, протектор другого рисунка. Ахметов: сорок третий; изъяла всё, что у него есть, — импортные туфли, подошва гладкая, кожаная, и зимние ботинки, протектор иной, пореза нет. Жумабаева: тридцать седьмой. Мужских следов у гаража ни одна из этих пар не оставила. Пары с порезом на каблуке среди того, что мне принесли, нет.", "5cdb3307-fe10-53c5-a365-6998256b7d7a": "Вы приносите Сеитовой конверт «на похороны» и напоминаете: пальцы того, кто его принёс, сняты с люка в подвале Шмидтов.\nОна молча кладёт пять купюр рядом с листами ксерокопий и ведёт линейкой по строчкам.\n— Все пять есть в копиях выкупа. Серия, номер — совпадение полное. Протокол сравнения подпишу сегодня.", "c2c5ba62-e24e-523f-93bc-d8909b28e717": "— Дактокарта Бекенова. — Сеитова кладёт рядом две кальки. — Второй набор с крышки люка — его, по восьми признакам. Ахметова откатала тоже, он пришёл сам: с люком не совпадает. Кан смотрел кисти у обоих — свежих повреждений нет. Кровь у Бекенова — вторая группа, справка Кана. Абишев по ГАИ: водительского удостоверения и машины у Бекенова нет, говорит, что водить умеет. Свела в одну бумагу, чтобы вы не бегали по этажам.", "43eaf70c-177d-516a-9ab2-7aecc9633e33": "— Раз не угар, смотреть надо машину, а не протокол. — Сеитова возвращается со стоянки Медеуского РОВД в мокрых по колено брюках. — Осмотрела. В колёсных арках жёлтая глина, плотная, налипла слоем. Такая бывает на немощёных улицах частного сектора — у Горного Гиганта, например, такие улицы. На Кок-Тобе к даче асфальт и щебень, там её не наберёшь. Руль: ни одного отпечатка. Ни чужого, ни хозяйского. Последним машину вёл человек в перчатках. Кто — не моя графа. Привезёте образец грунта — сравню."}'::jsonb, '[{"id": "R03", "on": "b4e6a60f-b233-543e-b3b1-ae0a1427b6a1", "requires": [], "text": "Сеитова раскладывает на капоте служебного «уазика» кальку и линейку.\n— Два типа следов. Первый: мужская зимняя обувь, сорок третий размер, протектор глубокий, на каблуке косой порез, около сантиметра. Лежат под тонким слоем снега. Снег здесь, по метеостанции, пошёл около часа ночи на воскресенье. Значит, следы ночные, до часа. Второй: женская обувь, тридцать седьмой. Эти под подмёрзшей коркой слякоти, оставлены раньше, засветло, пока грязь была мягкой. Борозды: две, параллельные, со стороны водительской двери. Так волочатся каблуки. Тело несли, ноги тащились по земле. Чьё — не скажу. Скажу размер.", "grants": ["60950128-af31-513e-b8de-bb87b02332cc"]}, {"id": "R24", "on": "46e78eb0-d057-5e5d-8a00-81457f8f3d20", "requires": ["4f67be3f-f5f7-5ab5-bb69-611053df3042"], "text": "— Три тысячи. Тридцать купюр по сто. — Сеитова не поднимает головы от стола. — Сверила с ксерокопиями: серия, номер, у двух купюр надрыв на краю, на копии он тоже виден. Все тридцать есть в копиях выкупа. Совпадение полное. Протокол сравнения подпишу сегодня. Как они попали к нему за подкладку — не моя графа.", "grants": ["d91852b9-daca-5340-80c9-a13cffe680cc"]}, {"id": "R27", "on": "00b31a8e-e1ee-5474-a323-177b43b153d3", "requires": ["60950128-af31-513e-b8de-bb87b02332cc"], "text": "— Сорок третий. Протектор тот же. Порез на каблуке косой, около сантиметра, края совпадают со слепком у гаража. Ботинки мыли, но в шве у подошвы грязь осталась, на экспертизу хватит. Подошву сравнила с калькой по шести точкам, все шесть совпали. — Сеитова снимает перчатки. — Эти ботинки оставили мужские следы у гаража дачи. Чьи ноги были в ботинках — вопрос не ко мне.", "grants": ["6fc41a46-a0eb-5890-9b26-3b19bcef490d"]}, {"id": "R28", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": ["4f67be3f-f5f7-5ab5-bb69-611053df3042"], "text": "— Доллары из мешка с рисом. — Сеитова кладёт на стол стопку протоколов и придвигает к ней листы ксерокопий. — Пересчитала при понятых, переписала номера, сверила с копиями Ахметова лист за листом. Каждая купюра из тайника есть в копиях выкупа. Ни одной лишней, ни одной чужой. Резинки банковские, описаны. Рис описан отдельно, если вам интересно.", "grants": ["107fcb2c-e909-5f81-bba4-d218265227c5"]}, {"id": "R30", "on": "4f67be3f-f5f7-5ab5-bb69-611053df3042", "requires": ["5cdb3307-fe10-53c5-a365-6998256b7d7a", "f725c4c5-f254-5c01-b718-3531a957102a"], "text": "Вы кладёте рядом с конвертом «на похороны» показания Шнайдер: тот, кто принёс конверт, в субботу вечером был у дома Шмидтов.\n— Конверт от матери покойного. Пять купюр по сто, новые, «с маленькой головой». — Сеитова раскладывает купюры рядом с листами ксерокопий. — Сверила номера. Все пять есть в копиях выкупа. Совпадение полное. Надпись карандашом «От Фархада — на похороны» внесена в протокол. Больше по конверту ничего.", "grants": ["26a10711-a53c-5105-9ed4-190697869496"]}, {"id": "R47", "on": "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44", "requires": [], "text": "Сеитова вскрывает корпус пейджера над лотком, сливает мутную воду и оставляет плату сохнуть на чуть тёплой батарее. Наутро ставит новый элемент питания.\n— Включился. — Она поворачивает к вам экран с бледными цифрами. — Последнее принятое сообщение в памяти: четверг, двадцать первое, семнадцать тридцать пять. Позже — ничего. В воде аппарат не принимает. Что на него слали после, знает оператор, это к Абишеву. Калитку я сфотографировала. Выводов по ней не делаю.", "grants": ["7ada2011-2720-5b69-8a9c-9291fdad70e9"]}, {"id": "R50", "on": "60950128-af31-513e-b8de-bb87b02332cc", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "— Обувь. — Сеитова раскладывает кальки веером. — Нуртазин: форменные ботинки, сорок третий, протектор другого рисунка. Ахметов: сорок третий; изъяла всё, что у него есть, — импортные туфли, подошва гладкая, кожаная, и зимние ботинки, протектор иной, пореза нет. Жумабаева: тридцать седьмой. Мужских следов у гаража ни одна из этих пар не оставила. Пары с порезом на каблуке среди того, что мне принесли, нет.", "grants": ["7a9bdd9a-4323-5342-a3bd-24301a6d6e88"]}, {"id": "R59", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": ["4f67be3f-f5f7-5ab5-bb69-611053df3042", "27ae146a-a05c-5e7a-84a1-899c35e883e4"], "text": "Вы приносите Сеитовой конверт «на похороны» и напоминаете: пальцы того, кто его принёс, сняты с люка в подвале Шмидтов.\nОна молча кладёт пять купюр рядом с листами ксерокопий и ведёт линейкой по строчкам.\n— Все пять есть в копиях выкупа. Серия, номер — совпадение полное. Протокол сравнения подпишу сегодня.", "grants": ["26a10711-a53c-5105-9ed4-190697869496"]}, {"id": "R60", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "— Дактокарта Бекенова. — Сеитова кладёт рядом две кальки. — Второй набор с крышки люка — его, по восьми признакам. Ахметова откатала тоже, он пришёл сам: с люком не совпадает. Кан смотрел кисти у обоих — свежих повреждений нет. Кровь у Бекенова — вторая группа, справка Кана. Абишев по ГАИ: водительского удостоверения и машины у Бекенова нет, говорит, что водить умеет. Свела в одну бумагу, чтобы вы не бегали по этажам.", "grants": ["9281d556-d163-5537-a0e2-e4cd2e635ba5"]}, {"id": "R64", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "— Раз не угар, смотреть надо машину, а не протокол. — Сеитова возвращается со стоянки Медеуского РОВД в мокрых по колено брюках. — Осмотрела. В колёсных арках жёлтая глина, плотная, налипла слоем. Такая бывает на немощёных улицах частного сектора — у Горного Гиганта, например, такие улицы. На Кок-Тобе к даче асфальт и щебень, там её не наберёшь. Руль: ни одного отпечатка. Ни чужого, ни хозяйского. Последним машину вёл человек в перчатках. Кто — не моя графа. Привезёте образец грунта — сравню.", "grants": ["3772cdd6-1fe9-52d0-a268-3f82441220c7"]}]'::jsonb, null, true, false, true, (select portrait_url from characters where name ilike '%Сеитова%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1), 'Криминалист ЭКО');
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url, specialization) values ('14e9bc6d-22f0-5005-b51c-e0678d8fa225', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '006a31f4-baeb-5b53-9a87-6a397ba18362', 'Ринат Абишев', 'Оператор ИВЦ ГУВД', 'Ринат Абишев, оператор ИВЦ: небритый, в свитере с оленями, с кружкой остывшего чая среди картотечных ящиков.
— Вы с запросом? Становитесь в очередь. Шучу. Очереди нет, есть только я.', '[{"q": "Что вы можете проверить?", "a": "— Судимости, дактокарты, адресное бюро, машины через ГАИ. Могу написать запрос на АТС, в пейджинговую, в электросети. Всё по бумаге, всё через день, и всё с моей подписью, которую никто не читает. Компьютер у нас один, и на нём бухгалтерия играет в «Тетрис»."}, {"q": "Что ещё имеет смысл проверить?", "a": "— Если у вас похищение и дом, где держали, — проверяйте всех, кто в тот вечер чем-то подтверждал, где он был. Свет, телефон, смены. Свет по районам я могу поднять отдельно на каждую улицу, если скажете какую. Электросети, слава богу, пишут всё, даже то, что не включили.", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931", "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba"]}, {"q": "Как убийца ночью спустился с Кок-Тобе, если машину оставил в гараже?", "a": "— Пешком, а внизу частника поймал. Как все. Частника не найдёшь, они в журналы не пишутся. В субботнюю ночь по городу бомбит каждый второй, у кого есть «копейка» и бензин. Это не след, это фон. Ищите то, что кто-нибудь записал.", "requires": ["3772cdd6-1fe9-52d0-a268-3f82441220c7"]}]'::jsonb, '{"1ac01ab0-e8f1-5009-9640-d18dfa4f5e44": "Абишев держит мёртвый пейджер двумя пальцами, как дохлую мышь.\n— Утопленник. Ладно, номер на крышке живой. Позвонил в пейджинговую, девочки там нормальные, за шоколадку журнал подняли. Значит, так. С вечера четверга до субботы на этот номер диктовали: из офиса — «СРОЧНО ПЕРЕЗВОНИ», несколько раз, и от матери. В офисе говорят: не перезвонил ни разу. Прочитал он или нет — этого никто на свете не знает, пейджер работает в одну сторону: оператор отправил, а дальше хоть в арык. — Пауза. — А нашли вы его, кстати, где? В арыке. Ну вот. Вывод сами делайте, мне за выводы не доплачивают.", "43eaf70c-177d-516a-9ab2-7aecc9633e33": "— Отключение света, значит. — Абишев листает протокол и хмыкает. — РОВД даже не проверил, было ли. Ладно, я проверил, мне не трудно, мне всё равно не платят. Написал диспетчеру районных электросетей запрос по Кок-Тобе, потом съездил сам: бумагу без печати не дают. Вот. В субботу с девятнадцати ноль-ноль до двух ночи район Кок-Тобе обесточен по графику. Про другие районы не спрашивал — у них на каждый район своя бумага и своя очередь. Так что свет на даче действительно не горел. Тут РОВД не соврал. Поздравляю их от всей души.", "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba": "Абишев выслушивает вас и откидывается на стуле так, что тот скрипит.\n— Пальцы на керосиновой лампе в доме у Горного Гиганта. А сам он в это время, по его словам, сидел при свечке в «Орбите». Понял, что вам нужно. Тогда я запрашивал только Кок-Тобе — кто ж знал. Ладно. Отдельный запрос по «Орбите», сразу за пятницу и субботу, чтобы второй раз не бегать. — Через день он кладёт перед вами бумагу с печатью. — Ни в пятницу, ни в субботу там не отключали. Ни по графику, ни аварийно. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Это справка, не обвинение. Обвинять будете вы.", "e4e94374-000e-52e3-bb26-9bec42b1c55b": "— Незнакомый номер, суббота, пятнадцать тридцать. Хорошо, что у мамы АОН на девяносто девять ячеек, а не на двадцать: за два дня соболезнований его бы вытеснило. — Абишев переписывает цифры на сигаретную пачку. — Частный сектор под горами, по первым цифрам видно. Ждите. — Через час он возвращается с листком. — Есть. Телефон зарегистрирован на Шмидта Г. Выбыл в ФРГ, на постоянное. Адрес — частный сектор у Горного Гиганта. Участковый тамошний говорит: дом пустой, продаётся по доверенности. Телефон не отключён. А звонили, выходит, из пустого дома. На кого доверенность — это к нотариусу, а нотариусы у нас любят бумагу с печатью и неделю сроку.", "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e": "— Номер, который ваш финансист запомнил с АОН? — Абишев хмыкает. — Бухгалтеры — лучшие свидетели, цифры помнят лучше лиц. Пробил через адресное бюро. Шмидт Г., выбыл на постоянное жительство в ФРГ. Частный сектор у Горного Гиганта. Участковый говорит: дом пустой, продаётся по доверенности, на кого — не знает, это к нотариусу. Телефон в доме не отключён. И с него, выходит, в субботу звонили.", "c2c5ba62-e24e-523f-93bc-d8909b28e717": "— Пальцы с люка и с лампы. Гульнара сняла чисто: на керосиновой копоти пальцы как печать. — Абишев зевает, не прикрываясь. — Сравнивал вручную, по картотеке, всю ночь, глаза как у кролика. Начал с тех, кто в вашем деле мелькает и у кого есть дактокарта. Есть совпадение. Мамаджанов Фархад, судим в девяносто четвёртом, таможенное дело. Второй набор на люке в картотеке не значится: человек несудимый, таких у меня полгорода, и на всех карточек нет. И ещё. В учётном деле лежит медкарта из колонии. Группа крови — вторая. Делайте с этим что хотите.", "be5c249c-d25f-5239-865f-5aef2088bc61": "— Пейджер охранника? — Абишев вертит его в руках. — Логику вашу понял: похитители знали и пустой дом, и что хозяин по четвергам ездит без шофёра. Пустой дом — это бумаги и нотариус. Четверги — это люди, и знали их на базе. Ладно. Сообщения он стёр, молодец. Только у пейджинговой свой журнал: что им диктуют, то они и пишут. — Он кладёт перед вами листок, переписанный от руки. — Четверг, двадцать первое. Шестнадцать тридцать. Абонент Нуртазин. Текст: «ЧЕТВЕРГ В СИЛЕ? Ф.». Кто такой «Ф.», оператор не спрашивает, ей за это не доплачивают. Как и мне.", "f725c4c5-f254-5c01-b718-3531a957102a": "— Подождите. Бабушка видела его «Волгу» у дома Шмидтов в субботу вечером? А он вам говорил — сидел в «Орбите» при свечке. — Абишев роется в бумагах. — «Орбиту» я не проверял, проверял Кок-Тобе. Сейчас. — Он звонит, вполголоса ругается с кем-то, ждёт, пишет. — Диспетчер говорит: по «Орбите» ни в пятницу, ни в субботу отключений не было. Свет горел. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Бумагу пришлют завтра, но знать это вы можете уже сейчас.", "b229ab87-5e5b-5f61-8a7b-18c17718e4cf": "— Даты свёл, раз уж у меня все бумаги. — Абишев рисует таблицу на обороте старой ориентировки. — Чайхана, где охраннику долг списали, — девятое, суббота, за две недели до похищения. «Волга» у ворот базы — четырнадцатое, за неделю. Крик «месяц тебе, или сядешь» — шестнадцатое, за пять дней. Похищение — двадцать первое. Получается, к шестнадцатому наводка уже куплена и ворота высмотрены. Кто там потом на кого кричал, плану было без разницы. Это не вывод, это календарь."}'::jsonb, '[{"id": "R02", "on": "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44", "requires": [], "text": "Абишев держит мёртвый пейджер двумя пальцами, как дохлую мышь.\n— Утопленник. Ладно, номер на крышке живой. Позвонил в пейджинговую, девочки там нормальные, за шоколадку журнал подняли. Значит, так. С вечера четверга до субботы на этот номер диктовали: из офиса — «СРОЧНО ПЕРЕЗВОНИ», несколько раз, и от матери. В офисе говорят: не перезвонил ни разу. Прочитал он или нет — этого никто на свете не знает, пейджер работает в одну сторону: оператор отправил, а дальше хоть в арык. — Пауза. — А нашли вы его, кстати, где? В арыке. Ну вот. Вывод сами делайте, мне за выводы не доплачивают.", "grants": ["7ada2011-2720-5b69-8a9c-9291fdad70e9"]}, {"id": "R10", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "— Отключение света, значит. — Абишев листает протокол и хмыкает. — РОВД даже не проверил, было ли. Ладно, я проверил, мне не трудно, мне всё равно не платят. Написал диспетчеру районных электросетей запрос по Кок-Тобе, потом съездил сам: бумагу без печати не дают. Вот. В субботу с девятнадцати ноль-ноль до двух ночи район Кок-Тобе обесточен по графику. Про другие районы не спрашивал — у них на каждый район своя бумага и своя очередь. Так что свет на даче действительно не горел. Тут РОВД не соврал. Поздравляю их от всей души.", "grants": ["9eedb06d-09c9-5fa6-b91f-46d7753f78b4"]}, {"id": "R11", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"], "text": "Абишев выслушивает вас и откидывается на стуле так, что тот скрипит.\n— Пальцы на керосиновой лампе в доме у Горного Гиганта. А сам он в это время, по его словам, сидел при свечке в «Орбите». Понял, что вам нужно. Тогда я запрашивал только Кок-Тобе — кто ж знал. Ладно. Отдельный запрос по «Орбите», сразу за пятницу и субботу, чтобы второй раз не бегать. — Через день он кладёт перед вами бумагу с печатью. — Ни в пятницу, ни в субботу там не отключали. Ни по графику, ни аварийно. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Это справка, не обвинение. Обвинять будете вы.", "grants": ["64b699fc-69d6-5bc3-ab81-b5a48df561bd"]}, {"id": "R12", "on": "e4e94374-000e-52e3-bb26-9bec42b1c55b", "requires": [], "text": "— Незнакомый номер, суббота, пятнадцать тридцать. Хорошо, что у мамы АОН на девяносто девять ячеек, а не на двадцать: за два дня соболезнований его бы вытеснило. — Абишев переписывает цифры на сигаретную пачку. — Частный сектор под горами, по первым цифрам видно. Ждите. — Через час он возвращается с листком. — Есть. Телефон зарегистрирован на Шмидта Г. Выбыл в ФРГ, на постоянное. Адрес — частный сектор у Горного Гиганта. Участковый тамошний говорит: дом пустой, продаётся по доверенности. Телефон не отключён. А звонили, выходит, из пустого дома. На кого доверенность — это к нотариусу, а нотариусы у нас любят бумагу с печатью и неделю сроку.", "grants": ["f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba"]}, {"id": "R13", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": [], "text": "— Номер, который ваш финансист запомнил с АОН? — Абишев хмыкает. — Бухгалтеры — лучшие свидетели, цифры помнят лучше лиц. Пробил через адресное бюро. Шмидт Г., выбыл на постоянное жительство в ФРГ. Частный сектор у Горного Гиганта. Участковый говорит: дом пустой, продаётся по доверенности, на кого — не знает, это к нотариусу. Телефон в доме не отключён. И с него, выходит, в субботу звонили.", "grants": ["f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba"]}, {"id": "R17", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba"], "text": "— Пальцы с люка и с лампы. Гульнара сняла чисто: на керосиновой копоти пальцы как печать. — Абишев зевает, не прикрываясь. — Сравнивал вручную, по картотеке, всю ночь, глаза как у кролика. Начал с тех, кто в вашем деле мелькает и у кого есть дактокарта. Есть совпадение. Мамаджанов Фархад, судим в девяносто четвёртом, таможенное дело. Второй набор на люке в картотеке не значится: человек несудимый, таких у меня полгорода, и на всех карточек нет. И ещё. В учётном деле лежит медкарта из колонии. Группа крови — вторая. Делайте с этим что хотите.", "grants": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"]}, {"id": "R20", "on": "be5c249c-d25f-5239-865f-5aef2088bc61", "requires": ["c4c95f03-86b0-5820-b9f4-736453e2dbef", "f725c4c5-f254-5c01-b718-3531a957102a"], "text": "— Пейджер охранника? — Абишев вертит его в руках. — Логику вашу понял: похитители знали и пустой дом, и что хозяин по четвергам ездит без шофёра. Пустой дом — это бумаги и нотариус. Четверги — это люди, и знали их на базе. Ладно. Сообщения он стёр, молодец. Только у пейджинговой свой журнал: что им диктуют, то они и пишут. — Он кладёт перед вами листок, переписанный от руки. — Четверг, двадцать первое. Шестнадцать тридцать. Абонент Нуртазин. Текст: «ЧЕТВЕРГ В СИЛЕ? Ф.». Кто такой «Ф.», оператор не спрашивает, ей за это не доплачивают. Как и мне.", "grants": ["c50332f2-fb14-5cff-9ea2-9581024ac2e3"]}, {"id": "R38", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "— Соседка назвала Мамаджанова? Он у нас есть: судим в девяносто четвёртом, таможня, дактокарта с тех пор лежит. — Абишев уже тянет с полки ящик картотеки. — Сравнивал вручную, полночи. Пальцы с крышки люка и с керосиновой лампы — его, Гульнара подтвердит. Второй набор с люка в картотеке не значится: несудимый. И раз уж я в его деле копался: медкарта колонии, группа крови вторая. Это вам на всякий случай, я в медицине не понимаю.", "grants": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"]}, {"id": "R48", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba"], "text": "— Подождите. Бабушка видела его «Волгу» у дома Шмидтов в субботу вечером? А он вам говорил — сидел в «Орбите» при свечке. — Абишев роется в бумагах. — «Орбиту» я не проверял, проверял Кок-Тобе. Сейчас. — Он звонит, вполголоса ругается с кем-то, ждёт, пишет. — Диспетчер говорит: по «Орбите» ни в пятницу, ни в субботу отключений не было. Свет горел. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Бумагу пришлют завтра, но знать это вы можете уже сейчас.", "grants": ["64b699fc-69d6-5bc3-ab81-b5a48df561bd"]}, {"id": "R51", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": [], "text": "— «Волга» с одной фарой, говорите? — Абишев тянется за сигаретами. — По вашему кругу запросил ИЦ и ГАИ. Мамаджанов Ф.: ГАЗ-24, «Волга», белая. Что у неё с фарами, ГАИ не пишет, у них в карточке фар нет. Ахметов: ВАЗ-2109, белая; попросил гаишников глянуть у офиса — фары целы, обе. Жумабаева: «Таврия», красная. Нуртазин: личной машины нет, ездит на служебном «уазике» агентства. Белых — две. Остальное — ваши глаза.", "grants": ["d8f33493-fc81-5e50-af40-37d9500040b6"]}, {"id": "R57", "on": "b229ab87-5e5b-5f61-8a7b-18c17718e4cf", "requires": ["0a295d5f-e115-5c89-a26a-5992761304a0", "c4c95f03-86b0-5820-b9f4-736453e2dbef"], "text": "— Даты свёл, раз уж у меня все бумаги. — Абишев рисует таблицу на обороте старой ориентировки. — Чайхана, где охраннику долг списали, — девятое, суббота, за две недели до похищения. «Волга» у ворот базы — четырнадцатое, за неделю. Крик «месяц тебе, или сядешь» — шестнадцатое, за пять дней. Похищение — двадцать первое. Получается, к шестнадцатому наводка уже куплена и ворота высмотрены. Кто там потом на кого кричал, плану было без разницы. Это не вывод, это календарь.", "grants": ["06da149b-c92c-54fa-a5f5-b78ff87dbc92"]}, {"id": "R58", "on": "be5c249c-d25f-5239-865f-5aef2088bc61", "requires": ["c4c95f03-86b0-5820-b9f4-736453e2dbef", "c2c5ba62-e24e-523f-93bc-d8909b28e717"], "text": "— Подвал в пустом доме за один вечер не готовят: матрас, верёвки, ведро. Ждали заранее — и ждали именно в четверг. Значит, кто-то знал, что по четвергам хозяин едет без шофёра, а это знали на базе. — Абишев откладывает пейджер охранника. — Журнал пейджинговой за двадцать первое: шестнадцать тридцать, абонент Нуртазин, текст «ЧЕТВЕРГ В СИЛЕ? Ф.». Это всё, что у них есть. Расшифровку подписи вам никто не даст.", "grants": ["c50332f2-fb14-5cff-9ea2-9581024ac2e3"]}, {"id": "R61", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba"], "text": "— Высокий молодой парень вышел из «Волги» вместе с Мамаджановым? Значит, смотрим, кто у Мамаджанова в городе молодой. — Абишев снимает с полки учётное дело девяносто четвёртого года и листает анкету. — Графа «родственники»: двоюродная сестра, Бекенова, Талгарский район. Дальше адресное бюро. По городу прописан один Бекенов оттуда: Олжас, двадцать два года, временная прописка — общежитие у Зелёного базара, комната четыреста двенадцать. Племянник, выходит. Это фамилия и адрес. Кто он вам — разбирайтесь сами.", "grants": ["6a92b637-cb0c-5bf4-8495-f503839bf08c"]}, {"id": "R62", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"], "text": "— Курьер на остановке: высокий, молодой, куртка, ушанка. И пальцы Мамаджанова в том подвале. Хотите знать, кто у Мамаджанова в городе из молодых. — Абишев снова достаёт учётное дело девяносто четвёртого года. — Анкета, графа «родственники»: двоюродная сестра, Бекенова, Талгарский район. Адресное бюро: в городе временно прописан Бекенов Олжас, двадцать два года, оттуда же, — общежитие у Зелёного базара, комната четыреста двенадцать. Справка как справка.", "grants": ["6a92b637-cb0c-5bf4-8495-f503839bf08c"]}]'::jsonb, null, true, false, true, (select portrait_url from characters where name ilike '%Абишев%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1), 'Оператор ИВЦ ГУВД');
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url, specialization) values ('a6c62ec0-5ff9-53a5-b9a2-20898741074b', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '006a31f4-baeb-5b53-9a87-6a397ba18362', 'Юрий Николаевич Кан', 'Судмедэксперт', 'Юрий Николаевич Кан, судмедэксперт, тридцать лет в профессии. Халат, нарукавники, очки на цепочке. Говорит негромко и всех зовёт «голубчик».
— Давайте, что у вас. Покойники не торопятся, а я тороплюсь: у меня их сегодня шесть.', '[{"q": "В гараже можно угореть?", "a": "— Можно, голубчик. Каждую зиму привозят: свет отключили, человек сел погреться, а гараж закрыт. Только мне бумага нужна. Без направления я его не вскрою, хоть он мне сам приснится."}, {"q": "Насколько надёжна группа крови как улика?", "a": "— Группа крови исключает, но не называет. Вторая у каждого третьего в городе. Если не совпала — человек свободен. Если совпала — значит, вам надо искать дальше.", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"]}]'::jsonb, '{"e34a96b0-5d0e-5414-9ef3-048071ef84ed": "Кан снимает очки и долго протирает их полой халата.\n— Ну что, голубчик. Угоревших я за тридцать лет видел больше, чем вы живых генералов. Этот — не угоревший. Признаков угара нет, совсем. В машину его посадили, когда он уже не дышал. Удушение, сдавление шеи: лицо одутловатое, в глазах точечные кровоизлияния, — в РОВД даже не посмотрели. Суббота, около двадцати двух, час туда-сюда. Дальше. На запястьях слабые следы, будто вязали поверх рукавов. Щетина дня в два, обезвоживание, голод. Двое суток он где-то был, и не по своей воле. И последнее: под ногтями кровь. У него первая группа, под ногтями вторая. Чья — это уже не моя наука.", "abc6fac8-abbd-5589-b6b5-958cd368e7fe": "В кабинете, при двух понятых, Кан просит задержанного положить левую руку на стол и сам разматывает бинт — медленно, виток за витком.\n— Ожога, голубчик, нет. Ни пузыря, ни пятна. — Он берёт лупу. — Царапины. Три, параллельные, края дугой. Это ногти. Человеческие. Животное оставляет другие следы, на моём веку я их насмотрелся. Давность — четверо-шестеро суток, заживают; вечеру субботы не противоречит. Теперь второе. Медкарта из колонии: вторая группа. Под ногтями покойного — вторая. Чтобы вы не обрадовались раньше времени: вторая у каждого третьего в городе, сама по себе она ничего не доказывает. Царапины — отдельно, группа — отдельно. Складывать будете вы.", "54bf13bc-3525-5eec-9441-609d8ee21f59": "— Таблицу? Пожалуйста, голубчик. Запросил медкарты и учётные дела всех, кто у вас в деле с фамилией и адресом. — Кан надевает очки и читает с листа. — Мамаджанов — вторая, по медкарте колонии. Ахметов — вторая. Нуртазин — первая, из личного дела МВД, он у нас служил. Жумабаева — третья. Под ногтями — вторая. Двоим подходит, двоим нет. Группа крови — не отпечаток пальца, голубчик. Она закрывает двери, но не открывает их.", "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c": "Валентина Петровна вспомнила, что в воскресенье рука у него была расцарапана, — «собака на базаре». Кан кивает:\n— Посмотрим, голубчик. — В кабинете, при понятых, он разматывает бинт на кисти задержанного. — Ожога под бинтом нет. Царапины: три, параллельные, края дугой. Ногти, человеческие. От собаки так не бывает, поверьте старику: покусов и когтей я на своём веку насмотрелся. Давность — четверо-шестеро суток, заживают; с вечером субботы совместимо. Группа у него по медкарте колонии вторая, под ногтями покойного — тоже вторая. Это я описываю кисть. Выводы — ваши.", "b177dd97-7391-5f5e-8308-72a1073516c2": "— Задержанного парня, Бекенова, мне привели с утра. Кровь взял: вторая группа. — Кан дописывает строку в таблицу, которую составлял раньше. — Кисти смотрел у него и, для порядка, у Ахметова: тот пришёл сам, рукава засучил без уговоров. Свежих повреждений нет ни у того, ни у другого. Гульнара сверила дактокарту Бекенова со вторым набором с люка — его. С пальцами Ахметова тот набор не совпал. Ринат по ГАИ добавил: прав и машины у Бекенова нет, водить, по его словам, умеет. Я описываю, голубчик. Складываете вы."}'::jsonb, '[{"id": "R01", "on": "e34a96b0-5d0e-5414-9ef3-048071ef84ed", "requires": [], "text": "Кан снимает очки и долго протирает их полой халата.\n— Ну что, голубчик. Угоревших я за тридцать лет видел больше, чем вы живых генералов. Этот — не угоревший. Признаков угара нет, совсем. В машину его посадили, когда он уже не дышал. Удушение, сдавление шеи: лицо одутловатое, в глазах точечные кровоизлияния, — в РОВД даже не посмотрели. Суббота, около двадцати двух, час туда-сюда. Дальше. На запястьях слабые следы, будто вязали поверх рукавов. Щетина дня в два, обезвоживание, голод. Двое суток он где-то был, и не по своей воле. И последнее: под ногтями кровь. У него первая группа, под ногтями вторая. Чья — это уже не моя наука.", "grants": ["54bf13bc-3525-5eec-9441-609d8ee21f59"]}, {"id": "R29", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59", "cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "В кабинете, при двух понятых, Кан просит задержанного положить левую руку на стол и сам разматывает бинт — медленно, виток за витком.\n— Ожога, голубчик, нет. Ни пузыря, ни пятна. — Он берёт лупу. — Царапины. Три, параллельные, края дугой. Это ногти. Человеческие. Животное оставляет другие следы, на моём веку я их насмотрелся. Давность — четверо-шестеро суток, заживают; вечеру субботы не противоречит. Теперь второе. Медкарта из колонии: вторая группа. Под ногтями покойного — вторая. Чтобы вы не обрадовались раньше времени: вторая у каждого третьего в городе, сама по себе она ничего не доказывает. Царапины — отдельно, группа — отдельно. Складывать будете вы.", "grants": ["7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3"]}, {"id": "R49", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "— Таблицу? Пожалуйста, голубчик. Запросил медкарты и учётные дела всех, кто у вас в деле с фамилией и адресом. — Кан надевает очки и читает с листа. — Мамаджанов — вторая, по медкарте колонии. Ахметов — вторая. Нуртазин — первая, из личного дела МВД, он у нас служил. Жумабаева — третья. Под ногтями — вторая. Двоим подходит, двоим нет. Группа крови — не отпечаток пальца, голубчик. Она закрывает двери, но не открывает их.", "grants": ["b177dd97-7391-5f5e-8308-72a1073516c2"]}, {"id": "R52", "on": "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c", "requires": ["cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Валентина Петровна вспомнила, что в воскресенье рука у него была расцарапана, — «собака на базаре». Кан кивает:\n— Посмотрим, голубчик. — В кабинете, при понятых, он разматывает бинт на кисти задержанного. — Ожога под бинтом нет. Царапины: три, параллельные, края дугой. Ногти, человеческие. От собаки так не бывает, поверьте старику: покусов и когтей я на своём веку насмотрелся. Давность — четверо-шестеро суток, заживают; с вечером субботы совместимо. Группа у него по медкарте колонии вторая, под ногтями покойного — тоже вторая. Это я описываю кисть. Выводы — ваши.", "grants": ["7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3"]}, {"id": "R53", "on": "b177dd97-7391-5f5e-8308-72a1073516c2", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "— Задержанного парня, Бекенова, мне привели с утра. Кровь взял: вторая группа. — Кан дописывает строку в таблицу, которую составлял раньше. — Кисти смотрел у него и, для порядка, у Ахметова: тот пришёл сам, рукава засучил без уговоров. Свежих повреждений нет ни у того, ни у другого. Гульнара сверила дактокарту Бекенова со вторым набором с люка — его. С пальцами Ахметова тот набор не совпал. Ринат по ГАИ добавил: прав и машины у Бекенова нет, водить, по его словам, умеет. Я описываю, голубчик. Складываете вы.", "grants": ["9281d556-d163-5537-a0e2-e4cd2e635ba5"]}]'::jsonb, null, true, false, true, (select portrait_url from characters where name ilike '%Кан' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1), 'Судмедэксперт');
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url, specialization) values ('11b90ca2-3c48-573f-95ac-041cf0635f90', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '006a31f4-baeb-5b53-9a87-6a397ba18362', 'Аскар Бейсенов', 'Криминолог, доцент высшей школы МВД', 'Аскар Бейсенов, криминолог, доцент высшей школы МВД. Аккуратный пиджак, кожаный портфель, остро отточенный карандаш, которым он постукивает по блокноту.
— Изложите мне факты. Предположения оставьте себе.', '[{"q": "Чем вы можете помочь?", "a": "— Типологией. Я скажу вам, как обычно ведут себя люди в такой ситуации и кто в неё обычно попадает. Кто именно попал в вашу — это уже следствие, а не наука."}, {"q": "Почему семья молчала?", "a": "— Это, к сожалению, типично. Недоверие к милиции у нас старше нас с вами. Семья боится не столько похитителей, сколько того, что милиция их спугнёт. Учтите: молчание свидетеля — ещё не соучастие.", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"]}]'::jsonb, '{"b4e6a60f-b233-543e-b3b1-ae0a1427b6a1": "Бейсенов долго рассматривает фототаблицу и схему следов и постукивает карандашом по блокноту.\n— Позвольте, я сформулирую академически, а вы переведёте на язык протокола. Заложника, за которого получен выкуп, в типичном случае отпускают: мёртвый заложник для похитителя — только риск. Убивают после выкупа, как правило, в одной ситуации: когда похититель боится опознания. То есть жертва его знала. Далее. Инсценировку выполнял человек, который знал дачу, знал привычки покойного и рассчитывал на то, что семья промолчит. Это не залётные. Это круг: друзья семьи, партнёры, бывшие супруги, охрана. — Точка карандашом. — Имён я не называю. Я называю закономерность.", "0a295d5f-e115-5c89-a26a-5992761304a0": "Бейсенов раскладывает на столе четыре листка с показаниями — по датам, слева направо — и постукивает карандашом по каждому.\n— Позвольте сформулировать хронологически. Девятое ноября, суббота: разговор в чайхане, наводчику предлагают списать долг за сведения о четвергах. Четырнадцатое, четверг: белая «Волга» с разбитой фарой караулит у ворот базы. Шестнадцатое, суббота: покойный уличает своего финансиста — «месяц тебе, или сядешь». Двадцать первое: похищение. — Точка карандашом. — Подготовка началась за неделю до того, как у финансиста появилась причина. Как правило, мотив предшествует плану, а не наоборот. Имён я не называю. Я называю порядок дат."}'::jsonb, '[{"id": "R23", "on": "b4e6a60f-b233-543e-b3b1-ae0a1427b6a1", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59", "b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "Бейсенов долго рассматривает фототаблицу и схему следов и постукивает карандашом по блокноту.\n— Позвольте, я сформулирую академически, а вы переведёте на язык протокола. Заложника, за которого получен выкуп, в типичном случае отпускают: мёртвый заложник для похитителя — только риск. Убивают после выкупа, как правило, в одной ситуации: когда похититель боится опознания. То есть жертва его знала. Далее. Инсценировку выполнял человек, который знал дачу, знал привычки покойного и рассчитывал на то, что семья промолчит. Это не залётные. Это круг: друзья семьи, партнёры, бывшие супруги, охрана. — Точка карандашом. — Имён я не называю. Я называю закономерность.", "grants": ["3b4003bd-1d82-5ec7-b07b-4c54af3ac4c0"]}, {"id": "R56", "on": "0a295d5f-e115-5c89-a26a-5992761304a0", "requires": ["c4c95f03-86b0-5820-b9f4-736453e2dbef", "b229ab87-5e5b-5f61-8a7b-18c17718e4cf"], "text": "Бейсенов раскладывает на столе четыре листка с показаниями — по датам, слева направо — и постукивает карандашом по каждому.\n— Позвольте сформулировать хронологически. Девятое ноября, суббота: разговор в чайхане, наводчику предлагают списать долг за сведения о четвергах. Четырнадцатое, четверг: белая «Волга» с разбитой фарой караулит у ворот базы. Шестнадцатое, суббота: покойный уличает своего финансиста — «месяц тебе, или сядешь». Двадцать первое: похищение. — Точка карандашом. — Подготовка началась за неделю до того, как у финансиста появилась причина. Как правило, мотив предшествует плану, а не наоборот. Имён я не называю. Я называю порядок дат.", "grants": ["06da149b-c92c-54fa-a5f5-b78ff87dbc92"]}]'::jsonb, null, true, false, true, (select portrait_url from characters where name ilike '%Бейсенов%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1), 'Криминолог, доцент высшей школы МВД');
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('54b23338-3cf2-5d0a-99c4-91c0de226522', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Виктор Гринько', 'Водитель Игоря с 1995 года, бывший таксист из автопарка', 'Виктор Гринько, водитель покойного, ждёт у ворот дачи. Курит в кулак и смотрит на гараж так, будто гараж ему что-то должен. Кепка, старая «аляска», шофёрские руки.
— Это я его нашёл. Говорите, что надо, я покажу.', '[{"q": "Как вы нашли тело?", "a": "— Валентина Петровна в воскресенье с утра позвонила: съезди, Витя, проверь дачу. Я приехал в девять сорок, ворота гаража закрыты, внутри тихо. Открыл — он за рулём. Бак пустой, мотор холодный. Я к соседям, от них в милицию и звонил. Больше не трогал ничего."}, {"q": "Где вы были в субботу вечером?", "a": "— Ну... Таксовал. Частником, на своей «копейке». У Сартакова платили, сами знаете, сколько. Только Данияру не говорите, он не любит, когда водитель налево ездит."}, {"q": "Каким человеком был Игорь?", "a": "— Требовал много, платил мало. Не бил, не орал — почти. Не моё дело, каким он был. Моё дело — баранка."}]'::jsonb, '{"43eaf70c-177d-516a-9ab2-7aecc9633e33": "Виктор мнёт кепку и смотрит не на протокол, а на гараж.\n— Угорел, написали... Может, и угорел. Я вам так скажу. По четвергам он меня в пять отпускал. Всегда. «Витя, свободен, я сам». Садился и один сюда, на дачу, — это у него после развода повелось. Все знали: офис, охрана на КПП, кто угодно. И ещё. Неделю назад, тоже в четверг, выхожу с базы — у ворот стоит «Волга», двадцать четвёртая, белая. Левая фара разбита, не горит. Мужик за рулём курит и на ворота смотрит. Номер не запомнил, темно было. А фару запомнил. Я машины помню лучше, чем людей.", "b4e6a60f-b233-543e-b3b1-ae0a1427b6a1": "Виктор стоит у ворот гаража и внутрь не заходит.\n— Я его полтора года возил. Каждый день. Кроме четверга после пяти: в пять — «свободен, Витя», и сам за руль, и сюда, наверх. Один. После развода так стало. На базе это все знали, на КПП ему шлагбаум заранее поднимали. А ещё... В прошлый четверг у ворот базы белая «Волга» стояла. Двадцать четвёртая. Левая фара разбита. Мужик сидел, курил, на ворота смотрел. Я тогда подумал — клиента ждёт. Теперь не знаю, что и думать."}'::jsonb, '[{"id": "R04", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "Виктор мнёт кепку и смотрит не на протокол, а на гараж.\n— Угорел, написали... Может, и угорел. Я вам так скажу. По четвергам он меня в пять отпускал. Всегда. «Витя, свободен, я сам». Садился и один сюда, на дачу, — это у него после развода повелось. Все знали: офис, охрана на КПП, кто угодно. И ещё. Неделю назад, тоже в четверг, выхожу с базы — у ворот стоит «Волга», двадцать четвёртая, белая. Левая фара разбита, не горит. Мужик за рулём курит и на ворота смотрит. Номер не запомнил, темно было. А фару запомнил. Я машины помню лучше, чем людей.", "grants": ["c4c95f03-86b0-5820-b9f4-736453e2dbef"]}, {"id": "R05", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "Услышав про удушение, Виктор долго молчит.\n— Задушили... Тогда скажу. Я не стукач, но раз такое дело. В субботу, шестнадцатого, — за пять дней до того четверга, когда я его последний раз видел, — сижу в приёмной, дверь в кабинет неплотно закрыта. Игорь орёт на Данияра. Я его таким не слышал никогда. «Месяц тебе, или сядешь». Слово в слово. Данияр вышел белый как стена, папку к груди прижимает. Про что это — не знаю, я в бумаги не лезу. Моё дело — баранка.", "grants": ["0a295d5f-e115-5c89-a26a-5992761304a0"]}, {"id": "R45", "on": "b4e6a60f-b233-543e-b3b1-ae0a1427b6a1", "requires": [], "text": "Виктор стоит у ворот гаража и внутрь не заходит.\n— Я его полтора года возил. Каждый день. Кроме четверга после пяти: в пять — «свободен, Витя», и сам за руль, и сюда, наверх. Один. После развода так стало. На базе это все знали, на КПП ему шлагбаум заранее поднимали. А ещё... В прошлый четверг у ворот базы белая «Волга» стояла. Двадцать четвёртая. Левая фара разбита. Мужик сидел, курил, на ворота смотрел. Я тогда подумал — клиента ждёт. Теперь не знаю, что и думать.", "grants": ["c4c95f03-86b0-5820-b9f4-736453e2dbef"]}]'::jsonb, null, false, false, true, (select portrait_url from characters where name ilike '%Гринько%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1));
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('96e916c8-7fd0-5edc-a4fe-1a6aeda231bf', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Алия Сартакова (Жумабаева)', 'Бывшая жена Игоря, врач-анестезиолог городской больницы', 'У ворот тормозит красная «Таврия». Из неё выходит женщина в больничном пуховике поверх халата, видно, что прямо с дежурства.
— Алия. Бывшая жена. Приехала посмотреть, что вы делаете с моим домом.', '[{"q": "Когда вы последний раз были на даче?", "a": "— С лета не была. Что мне тут делать — любоваться на его машину в гараже, который строил мой отец?"}, {"q": "Вы ссорились с Игорем?", "a": "— Ссорились. На прошлой неделе, у его матери. Я крикнула: «Чтоб ты сдох с этим домом». Валентина Петровна вам, конечно, уже доложила или скоро доложит. Дачу строили на деньги от квартиры моих родителей, а оформил он её на себя. Вот и весь мой мотив, записывайте."}, {"q": "Как, по-вашему, он мог угореть?", "a": "— Легко. Он всю жизнь грелся в машине, вместо того чтобы починить котёл. Я ему десять лет говорила: угоришь. Как врач говорила."}, {"q": "Зачем вам была нужна папка с документами?", "a": "— Для иска. Адвокат сказал: без документов о приватизации даже разговаривать не о чем. Я её не украла. Я её забрала. Это мой дом, и он будет домом моей дочери.", "requires": ["42ea83ef-f3ad-504f-99e0-da4ecb9fe57d"]}]'::jsonb, '{"60950128-af31-513e-b8de-bb87b02332cc": "Алия смотрит на снимок следа и коротко, зло смеётся.\n— Тридцать седьмой. Мой. Ладно. Была. В пятницу, в три часа дня, — специально выбрала день, когда он точно на работе. Ворота и дом открыла своими старыми ключами, они у меня на одной связке: замки он так и не сменил, жадность. Забрала из дома папку о приватизации дачи — для адвоката, для иска. Гараж был пустой, машины не было. Никого не было. В субботу с восьми вечера до восьми утра я на дежурстве, в одиннадцать десять давала наркоз — экстренная операция, журнал дежурств, протокол с моей подписью. Проверяйте. Я хотела его засудить, а не убить."}'::jsonb, '[{"id": "R06", "on": "60950128-af31-513e-b8de-bb87b02332cc", "requires": [], "text": "Алия смотрит на снимок следа и коротко, зло смеётся.\n— Тридцать седьмой. Мой. Ладно. Была. В пятницу, в три часа дня, — специально выбрала день, когда он точно на работе. Ворота и дом открыла своими старыми ключами, они у меня на одной связке: замки он так и не сменил, жадность. Забрала из дома папку о приватизации дачи — для адвоката, для иска. Гараж был пустой, машины не было. Никого не было. В субботу с восьми вечера до восьми утра я на дежурстве, в одиннадцать десять давала наркоз — экстренная операция, журнал дежурств, протокол с моей подписью. Проверяйте. Я хотела его засудить, а не убить.", "grants": ["42ea83ef-f3ad-504f-99e0-da4ecb9fe57d"]}]'::jsonb, array['54bf13bc-3525-5eec-9441-609d8ee21f59','7ada2011-2720-5b69-8a9c-9291fdad70e9']::uuid[], false, true, true, (select portrait_url from characters where name ilike 'Алия%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1));
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('0e8eb7cc-a947-5525-80eb-0978454d919b', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Валентина Петровна Сартакова', 'Мать Игоря, учительница литературы на пенсии', 'Валентина Петровна встречает вас в прихожей — в чёрном платке, очень прямая, с сухими глазами. Протягивает руку, как на родительском собрании.
— Вы из ГУВД. Проходите. Только, пожалуйста, не при людях.', '[{"q": "Когда вы последний раз говорили с сыном?", "a": "— В четверг утром, по телефону. Он уехал по делам — думаю, в Бишкек, он туда часто ездил. Мы не волновались. Никаких звонков не было. А в воскресенье я послала Виктора на дачу, потому что... потому что мать чувствует."}, {"q": "Кто мог желать Игорю зла?", "a": "— Я не люблю наговаривать. Но вы всё равно узнаете. На прошлой неделе, вот здесь, за этим столом, его бывшая жена кричала: «Чтоб ты сдох с этим домом». При мне. При девочке это было бы невозможно, а при мне, видимо, можно."}, {"q": "Кто такой Фархад?", "a": "— Фархад-ака? Двадцать лет как родной. Игорь у него начинал, совсем мальчишкой. Когда-то каждую пятницу у меня ел плов. Потом были у них... разные годы. Но он пришёл. Многие не пришли, а он пришёл."}, {"q": "Почему вы не пошли в милицию?", "a": "— Потому что они сказали: внучку больше не увидите. Вы бы пошли? — Пауза. — Я не собрала всю сумму. Сорок вместо шестидесяти. Вот почему его убили, понимаете? Из-за двадцати тысяч, которых у меня не было. И ещё. Они знали про дачу, про четверги, про Дашу. Кто им это рассказал? Я знаю, кому был нужен этот дом.", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"]}, {"q": "Какой шарф был у Игоря?", "a": "— Серый, кашемировый, итальянский. Я его привезла из Москвы, ещё когда можно было ездить в Москву за шарфами. Он его носил всю осень. — Она смотрит на вас. — Вы его нашли. Где?", "requires": ["c2c5ba62-e24e-523f-93bc-d8909b28e717"]}]'::jsonb, '{"e4e94374-000e-52e3-bb26-9bec42b1c55b": "Валентина Петровна долго смотрит на красные цифры АОН, потом на свой блокнот и говорит не вам, а серой коробочке:\n— Игорь поставил, чтобы я знала, кто звонит. Вот и знаю. — Садится прямо, не касаясь спинки стула. — В четверг около девяти позвонили из автомата: шестьдесят тысяч долларов, пойдёте в милицию — Дашу не увидите. С Данияром мы собрали сорок. В субботу в половине четвёртого позвонили ещё раз, вот с этого номера, — Данияр стоял рядом, видел. Он отвёз деньги, вернулся, и с половины восьмого до половины второго мы сидели здесь, ждали. — Она нажимает кнопку памяти, и цифры гаснут. — Он так радовался этой коробочке. «Мама, теперь ты всё будешь знать».", "54bf13bc-3525-5eec-9441-609d8ee21f59": "Вы кладёте перед Валентиной Петровной заключение Кана и пейджер сына из арыка. И говорите то, что должны сказать: молчание Дашу не защитит, защитить её может только милиция.\nОна молчит так долго, что на кухне перестают звенеть посудой.\n— Я тридцать лет учила детей говорить правду. Тридцать лет. А сама... Хорошо. Четверг, около девяти, автомат: шестьдесят тысяч, иначе внучку не увидим. С Данияром собрали сорок. Суббота, половина четвёртого, второй звонок, номер в АОН. Данияр отвёз деньги и вернулся, был со мной с половины восьмого до половины второго. — Голос впервые ломается. — Я молчала, чтобы уберечь Дашу. А вышло — как у плохой ученицы: молчит, потому что не выучила.", "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44": "— Его пейджер. У ворот, в арыке... — Валентина Петровна переводит взгляд с пейджера на АОН, потом на блокнот. Цифры её почерком. — Он не уезжал в Бишкек. Это я придумала. В пятницу утром позвонила Виктору: «Игорь в Бишкеке, вы свободны». Он поверил. Он мне всегда верит. — Дальше она говорит коротко, как диктует: — Четверг, девять вечера, автомат: шестьдесят тысяч, иначе внучка. Собрали с Данияром сорок. Суббота, пятнадцать тридцать, этот номер. Данияр отвёз деньги, вернулся, был со мной с половины восьмого до половины второго. — Пауза. — Скажите Виктору сами. Я не смогу ему в глаза смотреть.", "f725c4c5-f254-5c01-b718-3531a957102a": "Вы говорите Валентине Петровне, что соседка Шмидтов видела Фархада у того дома в субботу вечером, в четверть седьмого.\nОна не отвечает. Встаёт, подходит к серванту, где за стеклом всё ещё стоит конверт, и долго смотрит на собственный карандашный почерк: «От Фархада — на похороны».\n— Двадцать лет, — говорит она наконец. — Вот на этом стуле. По пятницам плов. Игорь у него начинал мальчишкой. — Пауза. — В воскресенье он пришёл вечером, принёс вот это. Рука у него была расцарапана, свежо, красно. Я спросила — собака на базаре, говорит. А уже в пальто, в прихожей, взял меня за локоть и сказал тихо: «Бандиты сейчас такие, Валентина-апа. Береги Дашу. Никому ни слова». Я подумала: хоть один обо мне думает. — Она закрывает дверцу серванта. — Больше ничего не спрашивайте. Я не знаю, что это значит.", "27ae146a-a05c-5e7a-84a1-899c35e883e4": "Вы говорите Валентине Петровне, что пальцы Мамаджанова сняты с люка подвала, где держали Игоря.\nОна выходит в прихожую и останавливается у зеркала, всё ещё завешенного простынёй.\n— Вот здесь он стоял. В воскресенье, уже в пальто. — Голос ровный, учительский, только руки она держит сцепленными. — Принёс конверт на похороны. Рука расцарапана, свежая. Собака на базаре, сказал. А здесь, у двери, взял меня за локоть: «Бандиты сейчас такие, Валентина-апа. Береги Дашу. Никому ни слова». Двадцать лет он у меня за столом сидел. Я тогда подумала — бережёт. — Она поправляет простыню на зеркале, хотя та висит ровно. — Идите. Мне надо побыть одной."}'::jsonb, '[{"id": "R08", "on": "e4e94374-000e-52e3-bb26-9bec42b1c55b", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "Валентина Петровна долго смотрит на красные цифры АОН, потом на свой блокнот и говорит не вам, а серой коробочке:\n— Игорь поставил, чтобы я знала, кто звонит. Вот и знаю. — Садится прямо, не касаясь спинки стула. — В четверг около девяти позвонили из автомата: шестьдесят тысяч долларов, пойдёте в милицию — Дашу не увидите. С Данияром мы собрали сорок. В субботу в половине четвёртого позвонили ещё раз, вот с этого номера, — Данияр стоял рядом, видел. Он отвёз деньги, вернулся, и с половины восьмого до половины второго мы сидели здесь, ждали. — Она нажимает кнопку памяти, и цифры гаснут. — Он так радовался этой коробочке. «Мама, теперь ты всё будешь знать».", "grants": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "group": "group-1", "repeat_text": "«Я вам уже всё рассказала. Больше мне добавить нечего»."}, {"id": "R09", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": ["1ac01ab0-e8f1-5009-9640-d18dfa4f5e44"], "text": "Вы кладёте перед Валентиной Петровной заключение Кана и пейджер сына из арыка. И говорите то, что должны сказать: молчание Дашу не защитит, защитить её может только милиция.\nОна молчит так долго, что на кухне перестают звенеть посудой.\n— Я тридцать лет учила детей говорить правду. Тридцать лет. А сама... Хорошо. Четверг, около девяти, автомат: шестьдесят тысяч, иначе внучку не увидим. С Данияром собрали сорок. Суббота, половина четвёртого, второй звонок, номер в АОН. Данияр отвёз деньги и вернулся, был со мной с половины восьмого до половины второго. — Голос впервые ломается. — Я молчала, чтобы уберечь Дашу. А вышло — как у плохой ученицы: молчит, потому что не выучила.", "grants": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "group": "group-1", "repeat_text": "«Я вам уже всё рассказала. Больше мне добавить нечего»."}, {"id": "R46", "on": "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44", "requires": ["e4e94374-000e-52e3-bb26-9bec42b1c55b"], "text": "— Его пейджер. У ворот, в арыке... — Валентина Петровна переводит взгляд с пейджера на АОН, потом на блокнот. Цифры её почерком. — Он не уезжал в Бишкек. Это я придумала. В пятницу утром позвонила Виктору: «Игорь в Бишкеке, вы свободны». Он поверил. Он мне всегда верит. — Дальше она говорит коротко, как диктует: — Четверг, девять вечера, автомат: шестьдесят тысяч, иначе внучка. Собрали с Данияром сорок. Суббота, пятнадцать тридцать, этот номер. Данияр отвёз деньги, вернулся, был со мной с половины восьмого до половины второго. — Пауза. — Скажите Виктору сами. Я не смогу ему в глаза смотреть.", "grants": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "group": "group-1", "repeat_text": "«Я вам уже всё рассказала. Больше мне добавить нечего»."}, {"id": "R65", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "Вы говорите Валентине Петровне, что соседка Шмидтов видела Фархада у того дома в субботу вечером, в четверть седьмого.\nОна не отвечает. Встаёт, подходит к серванту, где за стеклом всё ещё стоит конверт, и долго смотрит на собственный карандашный почерк: «От Фархада — на похороны».\n— Двадцать лет, — говорит она наконец. — Вот на этом стуле. По пятницам плов. Игорь у него начинал мальчишкой. — Пауза. — В воскресенье он пришёл вечером, принёс вот это. Рука у него была расцарапана, свежо, красно. Я спросила — собака на базаре, говорит. А уже в пальто, в прихожей, взял меня за локоть и сказал тихо: «Бандиты сейчас такие, Валентина-апа. Береги Дашу. Никому ни слова». Я подумала: хоть один обо мне думает. — Она закрывает дверцу серванта. — Больше ничего не спрашивайте. Я не знаю, что это значит.", "grants": ["e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c"], "group": "group-2", "repeat_text": "«Я вам уже всё рассказала. Больше мне добавить нечего»."}, {"id": "R66", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "Вы говорите Валентине Петровне, что пальцы Мамаджанова сняты с люка подвала, где держали Игоря.\nОна выходит в прихожую и останавливается у зеркала, всё ещё завешенного простынёй.\n— Вот здесь он стоял. В воскресенье, уже в пальто. — Голос ровный, учительский, только руки она держит сцепленными. — Принёс конверт на похороны. Рука расцарапана, свежая. Собака на базаре, сказал. А здесь, у двери, взял меня за локоть: «Бандиты сейчас такие, Валентина-апа. Береги Дашу. Никому ни слова». Двадцать лет он у меня за столом сидел. Я тогда подумала — бережёт. — Она поправляет простыню на зеркале, хотя та висит ровно. — Идите. Мне надо побыть одной.", "grants": ["e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c"], "group": "group-2", "repeat_text": "«Я вам уже всё рассказала. Больше мне добавить нечего»."}]'::jsonb, null, false, false, true, (select portrait_url from characters where name ilike 'Валентина%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1));
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('753087d6-7c38-5bf7-889e-3c4477902369', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Зоя Михайловна Лукина', 'Соседка Валентины по лестничной площадке в «сталинке» на Абая, бухгалтер на пенсии', 'На кухне у Валентины Петровны распоряжается невысокая женщина в мохеровом берете, с полотенцем через плечо: кому чай, кому тарелку, кому на балкон с папиросой — «только дверь за собой закройте». Увидев удостоверение, поправляет берет.
— Лукина, Зоя Михайловна. Соседка, дверь напротив. Тридцать лет на этой площадке. Спрашивайте, я тут до вечера.', '[{"q": "Вы хорошо знали Игоря?", "a": "— С пелёнок. Вежливый был, здоровался всегда, сумки мне до двери нёс. Не курил, между прочим. Последние годы приезжал редко, на иномарке. — Она поджимает губы. — Я не сплетничаю, я констатирую: к матери надо ездить чаще."}, {"q": "Кто сейчас приходит к Валентине Петровне?", "a": "— Все. Из школы её бывшие, родня, с его работы. Фархад-ака с утра здесь, вот кто человек: и хлеба принёс, и Валентину Петровну под руку держит. Курит, правда, «Беломор», на балконе. Я ему ничего не говорю. У человека горе."}, {"q": "Вы что-нибудь слышали в выходные?", "a": "— Стены здесь толстые, сталинские. Но я слышала, что у неё что-то стряслось: ходила, ходила, ночью не ложилась. — Она мнёт полотенце. — Не спросила. Думала, давление. Надо было спросить. Вы это не записывайте.", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"]}]'::jsonb, '{"b170d031-ba6c-5e70-829f-cbd96f761931": "Зоя Михайловна, которая всё это время стояла в дверях кухни с полотенцем, откашливается.\n— Я не сплетничаю. Я констатирую. Если Валентина Петровна говорит, что Данияр был у неё в субботу, — был. Его белая «девятка» стояла под моим окном с вечера и до глубокой ночи, я её знаю, он вечно ставит колесом на газон. А около десяти, перед вторым «Временем», я вышла на площадку, потому что опять потянуло табаком. Стоял, курил. Заграничные, окурки в банке у мусоропровода. Я ему сказала: молодой человек, тут люди живут.", "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e": "— Данияр? Говорит, что был здесь в субботу? — Зоя Михайловна поджимает губы. — Был. Я не сплетничаю, я констатирую. «Девятка» его белая под окном стояла с вечера до глубокой ночи: я её видела, когда задёргивала шторы, и ещё раз — когда выключала телевизор. А около десяти, перед вторым «Временем», он курил на лестнице. Я вышла сказать, что у нас не вокзал. Он извинился. Вежливый. Но курил."}'::jsonb, '[{"id": "R54", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": [], "text": "Зоя Михайловна, которая всё это время стояла в дверях кухни с полотенцем, откашливается.\n— Я не сплетничаю. Я констатирую. Если Валентина Петровна говорит, что Данияр был у неё в субботу, — был. Его белая «девятка» стояла под моим окном с вечера и до глубокой ночи, я её знаю, он вечно ставит колесом на газон. А около десяти, перед вторым «Временем», я вышла на площадку, потому что опять потянуло табаком. Стоял, курил. Заграничные, окурки в банке у мусоропровода. Я ему сказала: молодой человек, тут люди живут.", "grants": ["4e8b269e-8c91-5629-b60d-13930fa7e61e"]}, {"id": "R55", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": [], "text": "— Данияр? Говорит, что был здесь в субботу? — Зоя Михайловна поджимает губы. — Был. Я не сплетничаю, я констатирую. «Девятка» его белая под окном стояла с вечера до глубокой ночи: я её видела, когда задёргивала шторы, и ещё раз — когда выключала телевизор. А около десяти, перед вторым «Временем», он курил на лестнице. Я вышла сказать, что у нас не вокзал. Он извинился. Вежливый. Но курил.", "grants": ["4e8b269e-8c91-5629-b60d-13930fa7e61e"]}]'::jsonb, null, false, false, true, null);
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('5b4c1ece-ba00-50d6-9113-73e03e05ccd8', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Фархад Мамаджанов', 'Бывший начальник отдела снабжения госбазы, в 1992 году — соучредитель кооператива вместе с Игорем', 'В проёме кухонной двери стоит высокий седой человек в старом драповом пальто и держит Валентину Петровну под локоть, как держат старших. Кивает вам первым.
— Мамаджанов, Фархад. Друг семьи. Если что нужно, я тут, дорогой.', '[{"q": "Кем вы приходитесь семье?", "a": "— Другом, дорогой. Двадцать лет за этим столом. Игорь у меня в госснабе начинал: инженер, мальчишка, глаза горят. Потом вместе кооператив открыли, в девяносто втором. Потом жизнь развела. Так бывает."}, {"q": "Когда вы последний раз видели Игоря?", "a": "— Осенью. На базу к нему заходил, по старой памяти. Посидели, поговорили. По-хорошему поговорили, слушай. Кто ж знал, что последний раз."}, {"q": "Чем занимается ваш племянник Олжас?", "a": "— Олжас? — Фархад впервые за весь допрос кашляет, глухо, долго, и вытирает губы платком. — Хороший мальчик, из аула, у сестры моей двоюродной сын. Мешки таскает на Зелёном, в общаге живёт. Я ему говорю: учись, а он мне: аке, деньги нужны. Что я ему скажу? Сам такой был. Его не трогай, дорогой. Он тут ни при чём.", "requires": ["cefb9e58-2cc4-5054-a43b-6216c7645217", "6a92b637-cb0c-5bf4-8495-f503839bf08c"]}, {"q": "Где вы были в субботу вечером?", "a": "— Похитили?.. — Он долго молчит, потом садится. — И Валентина-апа мне ни слова. Двадцать лет — и ни слова. — Где я был... Я же говорил тебе, дорогой. Дома, в «Орбите». Один — Зарина у родни в Ташкенте. Свет у нас отключили, сидел при свечке, чай пил. Никуда не выходил. Кто ж знал, что в ту ночь...", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"]}, {"q": "Вы знаете дом Шмидтов у Горного Гиганта?", "a": "— Шмидтов? Знаю. Хорошие люди, уехали к своим в Германию. Дом их продаю, помогаю, — сейчас все продают. Только я там с октября не был, дорогой. Ключи отдал покупателю, а кому — не помню, их у меня десять было, покупателей.", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"]}, {"q": "Где ваша дочь?", "a": "— В Ташкенте. У родни, с четверга. — Он впервые смотрит на вас не с обидой, а со страхом. — Её не трогай. Она ничего не знает. Ничего, слышишь? Хочешь меня — бери меня.", "requires": ["cefb9e58-2cc4-5054-a43b-6216c7645217"]}]'::jsonb, '{"43eaf70c-177d-516a-9ab2-7aecc9633e33": "Фархад берёт протокол двумя руками — левая кисть у него перевязана бинтом — и читает долго, шевеля губами.\n— Угорел... Грелся, значит. Эх, Игорь, Игорь. Мы с ним давно помирились, дорогой, ты не думай. Зла не держал. Дай бог каждому такого друга. — Заметив, куда вы смотрите, приподнимает забинтованную руку. — Это? Казан. Плов делал, обжёгся, как мальчишка. Заживёт. — Пауза. — А в субботу у нас в «Орбите» тоже свет отключили. Сидел один при свечке, как старик, чай пил. Зарина моя у родни в Ташкенте, с четверга. Думал, позвонит Игорь, а он... — Он кладёт протокол на стол и разглаживает его ладонью. — Пойду к Валентине-апа. Ей сейчас нельзя одной.", "009a36f7-b362-586d-8943-61cd46149c3c": "В кабинете Фархад сидит без пальто, в старом свитере, и впервые выглядит на свои годы. Вы кладёте перед ним запись КПП за двадцать восьмое октября и показания Ахметова. Он долго молчит. Потом говорит тихо и уже без «дорогой»:\n— Помирились... Нет. Не помирились. Я за него сидел. Полтора года. Ты знаешь, что такое полтора года, когда тебе сорок семь? Он мне обещал: доля твоя, семья твоя под присмотром. Я вышел, а базы моей нет, есть их АО. Я пришёл к нему по-человечески. А он мне — «завскладом». При своём счетоводе. — Кашель. — Да, обиделся. Только обиду в милицию не носят, слушай. Обида — не преступление.", "64b699fc-69d6-5bc3-ab81-b5a48df561bd": "— Свет был? — Фархад смотрит на справку электросетей так, будто она написана не по-русски. — Значит, перепутал. Не в субботу отключали, в пятницу. — Вы кладёте рядом показания соседки Шмидтов: белая «Волга», одна фара, четверть седьмого. Он кашляет, долго, до слёз, вытирает глаза ладонью. — Ну заезжал, да. Чего ты так смотришь. Показывал дом покупателю — дом по доверенности на мне, я имею право. Посидели с лампой, света же там не было. Он уехал, я тоже. А про свечку дома перепутал, говорю тебе: у нас в пятницу отключали. — Голос у него больше не отеческий. — Всё. Устал я, слушай.", "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3": "— Ногти. — Фархад смотрит на свою кисть, голую, без бинта, как на чужую. — Собака это. На базаре... — И сам себя поправляет: — Казан. Обжёгся я. — Пауза. Кан сказал при понятых, что ожога нет, и он это слышал. — Казан, собака... какая разница, дорогой. Вторая группа у половины базара. Ты меня за группу крови посадишь? — Он отворачивается к окну и долго молчит. Когда наконец говорит, то не вам: — Зарина... дочка у меня. Семнадцать лет. — И снова замолкает, и больше на этот допрос его не хватает.", "27ae146a-a05c-5e7a-84a1-899c35e883e4": "— Пальцы на лампе? — Фархад усмехается одним углом рта. — Конечно, мои. Я этот дом продаю. Лампы трогал, двери трогал, всё трогал. — Вы напоминаете: люк в подвал. И соседку — «Волга» у калитки в субботу вечером. Он молчит. — Говорил, с октября не был. Ну... заезжал. В субботу. Покупателю дом показывал, посидели с лампой — света же не было. Он уехал, я тоже. А про свечку дома — перепутал, у нас в пятницу отключали. — Он наконец смотрит на вас прямо. — Ты молодой ещё, дорогой. Не ищи там, где тебе не надо. Иногда лучше не найти.", "26a10711-a53c-5105-9ed4-190697869496": "Фархад смотрит на протокол сравнения купюр так, будто ему дали пощёчину.\n— Это от сердца было, — говорит он. И потом, совсем тихо: — Валентине-апа не говори. Как человека прошу. Двадцать лет я за её столом сидел... Пусть думает, что от сердца. — Он прячет руки в рукава свитера, как старик на остановке, и смотрит мимо вас, на дверь кабинета. — Больше ничего не скажу. Делай свою работу.", "5cdb3307-fe10-53c5-a365-6998256b7d7a": "— Конверт? Это я принёс, да. Свои, от сердца. Похороны сейчас сам знаешь сколько стоят, а Валентина-апа одна. — Фархад отмахивается перевязанной рукой. — Это? Казан, обжёгся, не обращай внимания. Мы с Игорем давно помирились, дорогой. Что было, то было, зла не держу. В субботу сидел у себя в «Орбите» один — Зарина у родни в Ташкенте, а у нас свет отключили, при свечке сидел. Кто ж знал, что он в ту ночь... — Он не договаривает. — Ты Валентину-апа сегодня не мучай, дорогой. Она держится, но это снаружи.", "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c": "Олжаса уводят. Фархад долго смотрит на закрывшуюся дверь кабинета, потом говорит медленно, по-отечески, в последний раз:\n— Мальчика пожалей. Он не знал. Я ему сказал — никто не пострадает, и сам тогда в это верил. Слушай сюда. Ерлану я долг списал за четверги, больше он ничего не знал. Игоря мы взяли. Я хотел свою долю. Только долю. А потом Олжас пришёл и сказал: он тебя узнал. И я понял: живой он меня посадит, а Зарина останется одна с моими долгами. Они к ней уже приходили, к моей дочери. Я его... сам. Один. Потом отвёз на Кок-Тобе, на его же машине, мотор завёл. Вниз пешком, внизу частника поймал — номера не помню, не спрашивай. Часть денег отдал кредитору. Остальное ты нашёл. — Кашель. — Пощады не прошу. Дочку только не трогайте.", "f725c4c5-f254-5c01-b718-3531a957102a": "Вы читаете Фархаду показания Шнайдер, строчку за строчкой. Из «Волги» вышли двое: он и высокий парень. Парень скоро ушёл пешком. Больше в тот вечер никто не приезжал. «Волга» простояла у калитки до половины второго ночи и уехала по свежему снегу.\nФархад слушает, глядя на свои руки.\n— Покупатель... — говорит он и не заканчивает. Долго кашляет. — Старуха не спит, значит. Всё видит. — Пауза. — Сейчас спросишь, как его зовут. Не спрашивай. Нету его.\nИ больше на этот допрос ничего не говорит."}'::jsonb, '[{"id": "R07", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "Фархад берёт протокол двумя руками — левая кисть у него перевязана бинтом — и читает долго, шевеля губами.\n— Угорел... Грелся, значит. Эх, Игорь, Игорь. Мы с ним давно помирились, дорогой, ты не думай. Зла не держал. Дай бог каждому такого друга. — Заметив, куда вы смотрите, приподнимает забинтованную руку. — Это? Казан. Плов делал, обжёгся, как мальчишка. Заживёт. — Пауза. — А в субботу у нас в «Орбите» тоже свет отключили. Сидел один при свечке, как старик, чай пил. Зарина моя у родни в Ташкенте, с четверга. Думал, позвонит Игорь, а он... — Он кладёт протокол на стол и разглаживает его ладонью. — Пойду к Валентине-апа. Ей сейчас нельзя одной.", "grants": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "abc6fac8-abbd-5589-b6b5-958cd368e7fe"]}, {"id": "R31", "on": "009a36f7-b362-586d-8943-61cd46149c3c", "requires": ["4cc34317-760f-577c-b05f-e0374aee4f23"], "text": "В кабинете Фархад сидит без пальто, в старом свитере, и впервые выглядит на свои годы. Вы кладёте перед ним запись КПП за двадцать восьмое октября и показания Ахметова. Он долго молчит. Потом говорит тихо и уже без «дорогой»:\n— Помирились... Нет. Не помирились. Я за него сидел. Полтора года. Ты знаешь, что такое полтора года, когда тебе сорок семь? Он мне обещал: доля твоя, семья твоя под присмотром. Я вышел, а базы моей нет, есть их АО. Я пришёл к нему по-человечески. А он мне — «завскладом». При своём счетоводе. — Кашель. — Да, обиделся. Только обиду в милицию не носят, слушай. Обида — не преступление.", "grants": []}, {"id": "R32", "on": "64b699fc-69d6-5bc3-ab81-b5a48df561bd", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "— Свет был? — Фархад смотрит на справку электросетей так, будто она написана не по-русски. — Значит, перепутал. Не в субботу отключали, в пятницу. — Вы кладёте рядом показания соседки Шмидтов: белая «Волга», одна фара, четверть седьмого. Он кашляет, долго, до слёз, вытирает глаза ладонью. — Ну заезжал, да. Чего ты так смотришь. Показывал дом покупателю — дом по доверенности на мне, я имею право. Посидели с лампой, света же там не было. Он уехал, я тоже. А про свечку дома перепутал, говорю тебе: у нас в пятницу отключали. — Голос у него больше не отеческий. — Всё. Устал я, слушай.", "grants": ["7188cb7d-2261-5a9c-8f78-e603caa6b31a"]}, {"id": "R33", "on": "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3", "requires": [], "text": "— Ногти. — Фархад смотрит на свою кисть, голую, без бинта, как на чужую. — Собака это. На базаре... — И сам себя поправляет: — Казан. Обжёгся я. — Пауза. Кан сказал при понятых, что ожога нет, и он это слышал. — Казан, собака... какая разница, дорогой. Вторая группа у половины базара. Ты меня за группу крови посадишь? — Он отворачивается к окну и долго молчит. Когда наконец говорит, то не вам: — Зарина... дочка у меня. Семнадцать лет. — И снова замолкает, и больше на этот допрос его не хватает.", "grants": []}, {"id": "R34", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "— Пальцы на лампе? — Фархад усмехается одним углом рта. — Конечно, мои. Я этот дом продаю. Лампы трогал, двери трогал, всё трогал. — Вы напоминаете: люк в подвал. И соседку — «Волга» у калитки в субботу вечером. Он молчит. — Говорил, с октября не был. Ну... заезжал. В субботу. Покупателю дом показывал, посидели с лампой — света же не было. Он уехал, я тоже. А про свечку дома — перепутал, у нас в пятницу отключали. — Он наконец смотрит на вас прямо. — Ты молодой ещё, дорогой. Не ищи там, где тебе не надо. Иногда лучше не найти.", "grants": ["7188cb7d-2261-5a9c-8f78-e603caa6b31a"]}, {"id": "R35", "on": "26a10711-a53c-5105-9ed4-190697869496", "requires": [], "text": "Фархад смотрит на протокол сравнения купюр так, будто ему дали пощёчину.\n— Это от сердца было, — говорит он. И потом, совсем тихо: — Валентине-апа не говори. Как человека прошу. Двадцать лет я за её столом сидел... Пусть думает, что от сердца. — Он прячет руки в рукава свитера, как старик на остановке, и смотрит мимо вас, на дверь кабинета. — Больше ничего не скажу. Делай свою работу.", "grants": []}, {"id": "R37", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": [], "text": "— Конверт? Это я принёс, да. Свои, от сердца. Похороны сейчас сам знаешь сколько стоят, а Валентина-апа одна. — Фархад отмахивается перевязанной рукой. — Это? Казан, обжёгся, не обращай внимания. Мы с Игорем давно помирились, дорогой. Что было, то было, зла не держу. В субботу сидел у себя в «Орбите» один — Зарина у родни в Ташкенте, а у нас свет отключили, при свечке сидел. Кто ж знал, что он в ту ночь... — Он не договаривает. — Ты Валентину-апа сегодня не мучай, дорогой. Она держится, но это снаружи.", "grants": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "abc6fac8-abbd-5589-b6b5-958cd368e7fe"]}, {"id": "R36", "on": "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c", "requires": ["6fc41a46-a0eb-5890-9b26-3b19bcef490d", "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3"], "text": "Олжаса уводят. Фархад долго смотрит на закрывшуюся дверь кабинета, потом говорит медленно, по-отечески, в последний раз:\n— Мальчика пожалей. Он не знал. Я ему сказал — никто не пострадает, и сам тогда в это верил. Слушай сюда. Ерлану я долг списал за четверги, больше он ничего не знал. Игоря мы взяли. Я хотел свою долю. Только долю. А потом Олжас пришёл и сказал: он тебя узнал. И я понял: живой он меня посадит, а Зарина останется одна с моими долгами. Они к ней уже приходили, к моей дочери. Я его... сам. Один. Потом отвёз на Кок-Тобе, на его же машине, мотор завёл. Вниз пешком, внизу частника поймал — номера не помню, не спрашивай. Часть денег отдал кредитору. Остальное ты нашёл. — Кашель. — Пощады не прошу. Дочку только не трогайте.", "grants": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"]}, {"id": "R63", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["7188cb7d-2261-5a9c-8f78-e603caa6b31a"], "text": "Вы читаете Фархаду показания Шнайдер, строчку за строчкой. Из «Волги» вышли двое: он и высокий парень. Парень скоро ушёл пешком. Больше в тот вечер никто не приезжал. «Волга» простояла у калитки до половины второго ночи и уехала по свежему снегу.\nФархад слушает, глядя на свои руки.\n— Покупатель... — говорит он и не заканчивает. Долго кашляет. — Старуха не спит, значит. Всё видит. — Пауза. — Сейчас спросишь, как его зовут. Не спрашивай. Нету его.\nИ больше на этот допрос ничего не говорит.", "grants": []}]'::jsonb, null, false, true, true, (select portrait_url from characters where name ilike '%Фархад%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1));
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('a7955352-673d-5ff7-bfcc-506079544d1f', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'Данияр Ахметов', 'Партнёр Игоря и финансист фирмы, по образованию экономист', 'Данияр Ахметов сидит в кабинете, где папки стоят по годам. Тёмный костюм, галстук, очки в тонкой оправе, на столе калькулятор и две ручки, уложенные параллельно.
— Ахметов. Финансовый директор. Чем могу помочь?', '[{"q": "Как дела у фирмы?", "a": "— В порядке. Оборот за третий квартал выше прошлогоднего на двенадцать процентов, задолженности по поставкам нет. Игорь мне доверял полностью. Полностью."}, {"q": "Где вы были в субботу вечером?", "a": "— Дома. Один. С девятнадцати ноль-ноль примерно до... до утра. Смотрел телевизор. Программу не помню. Это важно?"}, {"q": "Игорь кричал на вас: «Месяц тебе, или сядешь». О чём шла речь?", "a": "— Виктор. — Он снимает очки. — Хорошо. Был вопрос по деньгам. Я выводил средства на другую фирму. Полгода. Хотел купить квартиру в Москве и уехать: здесь всё рухнет, вы же видите. Игорь нашёл платёжки и дал мне месяц вернуть. Я собирался вернуть. Это хищение, я понимаю. Но это не убийство.", "requires": ["0a295d5f-e115-5c89-a26a-5992761304a0"]}, {"q": "Зачем вы сняли копии купюр?", "a": "— Потому что я не верил никому. Ни им, ни вам, извините. Если бы Игоря не отпустили, у кого-то должны были остаться номера. Я финансист. Я всё копирую. Это единственное, что я умею делать хорошо.", "requires": ["ea60506a-dfdb-5176-a63a-2fd3c47f8b6e"]}]'::jsonb, '{"b170d031-ba6c-5e70-829f-cbd96f761931": "Данияр снимает очки и кладёт их на стол дужками вверх, ровно.\n— Валентина Петровна сказала. Значит, всё. Да, знал. С пятницы. Она запретила идти в милицию, я согласился. Сорок тысяч взял из кассы, которой официально нет, и вернул туда то, что раньше вывел. В субботу в пятнадцать тридцать был у неё, когда позвонили, — номер на АОН видел сам. Оттуда с пакетом на остановку на Ташкентской, в семнадцать тридцать оставил под скамейкой. Темно. Парень: высокий, молодой, спортивная куртка, ушанка. Лица нет. Потом на базу: въехал в семнадцать пятьдесят пять, выехал в девятнадцать десять, на КПП записано. В девятнадцать тридцать вернулся к Валентине Петровне и сидел до часу тридцати. — Он открывает нижний ящик. — Копии всех купюр. Я не верил ни им, ни вам.", "e4e94374-000e-52e3-bb26-9bec42b1c55b": "Данияр смотрит на страницу блокнота, и на его лице появляется что-то вроде облегчения.\n— Это почерк Валентины Петровны. «Шестьдесят» — тысяч. «Семнадцать тридцать, Ташкентская». Вы уже всё поняли. — Он снимает очки. — Да. Знал с пятницы, в милицию не пошёл, она просила. Сорок тысяч взял из «чёрной» кассы, вернул туда то, что выводил. Этот номер на АОН в пятнадцать тридцать я видел своими глазами: я был там, когда звонили. В семнадцать тридцать оставил пакет на остановке. Темно. Высокий молодой парень, спортивная куртка, ушанка — лица не видел. Потом база, с семнадцати пятидесяти пяти до девятнадцати десяти, журнал КПП подтвердит. С половины восьмого до половины второго — снова у неё. — Он выдвигает ящик. — Копии купюр. Все. Возьмите.", "4cc34317-760f-577c-b05f-e0374aee4f23": "Данияр долго смотрит на строчку в журнале.\n— Двадцать восьмое октября. Шестнадцать десять. Да. Я был в кабинете. Фархад пришёл просить свою долю. Спокойно пришёл, вежливо, в галстуке. Вы знаете, что он сидел? В девяносто четвёртом, за товар нашей общей фирмы, — взял на себя. Полтора года. Игорь ему тогда обещал всё сохранить. А тут сказал при мне: «Я тебя садиться не просил. Хочешь — иди завскладом». Фархад ничего не ответил. Встал и ушёл. Молча. Я тогда подумал, что лучше бы он кричал.", "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba": "— Помирились? — Данияр впервые повышает голос и тут же снимает очки, словно испугавшись. — Он так сказал? Игорь его выгнал. При мне. Двадцать восьмого октября, в кабинете. Фархад пришёл просить свою долю, вежливо, в галстуке. Он ведь в девяносто четвёртом сел за товар нашей общей фирмы, взял всё на себя, полтора года отсидел. А Игорь ему: «Я тебя садиться не просил. Хочешь — иди завскладом». Фархад ушёл молча. Если это называется «помирились», то я не знаю, что такое ссора."}'::jsonb, '[{"id": "R14", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": [], "text": "Данияр снимает очки и кладёт их на стол дужками вверх, ровно.\n— Валентина Петровна сказала. Значит, всё. Да, знал. С пятницы. Она запретила идти в милицию, я согласился. Сорок тысяч взял из кассы, которой официально нет, и вернул туда то, что раньше вывел. В субботу в пятнадцать тридцать был у неё, когда позвонили, — номер на АОН видел сам. Оттуда с пакетом на остановку на Ташкентской, в семнадцать тридцать оставил под скамейкой. Темно. Парень: высокий, молодой, спортивная куртка, ушанка. Лица нет. Потом на базу: въехал в семнадцать пятьдесят пять, выехал в девятнадцать десять, на КПП записано. В девятнадцать тридцать вернулся к Валентине Петровне и сидел до часу тридцати. — Он открывает нижний ящик. — Копии всех купюр. Я не верил ни им, ни вам.", "grants": ["ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "4f67be3f-f5f7-5ab5-bb69-611053df3042"]}, {"id": "R15", "on": "e4e94374-000e-52e3-bb26-9bec42b1c55b", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "Данияр смотрит на страницу блокнота, и на его лице появляется что-то вроде облегчения.\n— Это почерк Валентины Петровны. «Шестьдесят» — тысяч. «Семнадцать тридцать, Ташкентская». Вы уже всё поняли. — Он снимает очки. — Да. Знал с пятницы, в милицию не пошёл, она просила. Сорок тысяч взял из «чёрной» кассы, вернул туда то, что выводил. Этот номер на АОН в пятнадцать тридцать я видел своими глазами: я был там, когда звонили. В семнадцать тридцать оставил пакет на остановке. Темно. Высокий молодой парень, спортивная куртка, ушанка — лица не видел. Потом база, с семнадцати пятидесяти пяти до девятнадцати десяти, журнал КПП подтвердит. С половины восьмого до половины второго — снова у неё. — Он выдвигает ящик. — Копии купюр. Все. Возьмите.", "grants": ["ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "4f67be3f-f5f7-5ab5-bb69-611053df3042"]}, {"id": "R16", "on": "4cc34317-760f-577c-b05f-e0374aee4f23", "requires": [], "text": "Данияр долго смотрит на строчку в журнале.\n— Двадцать восьмое октября. Шестнадцать десять. Да. Я был в кабинете. Фархад пришёл просить свою долю. Спокойно пришёл, вежливо, в галстуке. Вы знаете, что он сидел? В девяносто четвёртом, за товар нашей общей фирмы, — взял на себя. Полтора года. Игорь ему тогда обещал всё сохранить. А тут сказал при мне: «Я тебя садиться не просил. Хочешь — иди завскладом». Фархад ничего не ответил. Встал и ушёл. Молча. Я тогда подумал, что лучше бы он кричал.", "grants": ["009a36f7-b362-586d-8943-61cd46149c3c"]}, {"id": "R43", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "— Помирились? — Данияр впервые повышает голос и тут же снимает очки, словно испугавшись. — Он так сказал? Игорь его выгнал. При мне. Двадцать восьмого октября, в кабинете. Фархад пришёл просить свою долю, вежливо, в галстуке. Он ведь в девяносто четвёртом сел за товар нашей общей фирмы, взял всё на себя, полтора года отсидел. А Игорь ему: «Я тебя садиться не просил. Хочешь — иди завскладом». Фархад ушёл молча. Если это называется «помирились», то я не знаю, что такое ссора.", "grants": ["009a36f7-b362-586d-8943-61cd46149c3c"]}]'::jsonb, null, false, true, true, (select portrait_url from characters where name ilike '%Данияр%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1));
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('2d9e7245-2e05-5079-86f1-f9b2edb1f3e9', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'Ерлан Нуртазин', 'Бывший сержант милиции, уволен в 1994 году после истории со взяткой', 'Охранник на КПП, лет тридцати пяти, в камуфляже агентства и вязаной шапке. Увидев удостоверение, встаёт — старая привычка, — и тут же садится обратно.
— Нуртазин. Охрана объекта. Слушаю.', '[{"q": "Где вы были в субботу вечером?", "a": "— Находился на посту. С двадцати ноль-ноль до восьми ноль-ноль, смена. Отзвоны на пульт агентства каждый час, журнал смены у старшего. Проверяйте, я сам бы проверил."}, {"q": "Кто знал, что Игорь по четвергам ездит один?", "a": "— Да все знали. КПП, офис, грузчики. Он в пять водилу отпускал и сам за руль. Тайна, тоже мне."}, {"q": "Вы знаете Фархада Мамаджанова?", "a": "— Мамаджанова? — Пепел падает на колено. — Почти не знаю. Видел пару раз на базе, давно. Пожилой такой, кашляет. А что?", "requires": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba"]}, {"q": "Почему вы молчали?", "a": "— А ты знаешь, как сидят бывшие менты? Вот. Я думал: разговор у них, мужской. А потом его нашли — и я сказал себе: угорел. Угорел, и всё. Так легче было.", "requires": ["b229ab87-5e5b-5f61-8a7b-18c17718e4cf"]}]'::jsonb, '{"c50332f2-fb14-5cff-9ea2-9581024ac2e3": "Ерлан читает листок, и пепел с сигареты падает ему на колено.\n— Да чё ты... Ладно. Ладно. Фархад. В девяносто третьем мать на операцию легла, нужно было полторы тысячи долларов. Он дал. Без расписки. Я не вернул, меня из органов уволили, какие деньги. А за две недели до того — в субботу, девятого, в чайхане у Зелёного — он говорит: забудь долг, только скажи, когда Игорь один ездит. Поговорить, мол, по-мужски, без водилы. Я сказал: по четвергам. В четверг он мне на пейджер: «в силе?». Я перезвонил: в силе. Всё. Думал, разговор. В субботу находился на посту, с двадцати до восьми, отзвоны на пульт каждый час. А когда Игоря нашли — гнал от себя. Молчал.", "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db": "Ерлан слушает выдержку из показаний Мамаджанова и тушит сигарету о край стола, мимо пепельницы.\n— Сдал, значит, Фархад-ака. Ну да. Было. В девяносто третьем он мне полторы тысячи дал, на операцию матери, я не вернул. А девятого, в субботу, в чайхане у Зелёного — недели за две до всего — говорит: спишу, только скажи, когда Игорь без водилы ездит, поговорить надо по-мужски. Я сказал: по четвергам. В четверг пришло на пейджер «в силе?» — я перезвонил, подтвердил. Больше ничего не знал, хоть режь. Думал, разговор. В субботу был на смене, с двадцати до восьми, отзвоны на пульт каждый час. Проверяй."}'::jsonb, '[{"id": "R21", "on": "c50332f2-fb14-5cff-9ea2-9581024ac2e3", "requires": [], "text": "Ерлан читает листок, и пепел с сигареты падает ему на колено.\n— Да чё ты... Ладно. Ладно. Фархад. В девяносто третьем мать на операцию легла, нужно было полторы тысячи долларов. Он дал. Без расписки. Я не вернул, меня из органов уволили, какие деньги. А за две недели до того — в субботу, девятого, в чайхане у Зелёного — он говорит: забудь долг, только скажи, когда Игорь один ездит. Поговорить, мол, по-мужски, без водилы. Я сказал: по четвергам. В четверг он мне на пейджер: «в силе?». Я перезвонил: в силе. Всё. Думал, разговор. В субботу находился на посту, с двадцати до восьми, отзвоны на пульт каждый час. А когда Игоря нашли — гнал от себя. Молчал.", "grants": ["b229ab87-5e5b-5f61-8a7b-18c17718e4cf"]}, {"id": "R22", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": [], "text": "Ерлан слушает выдержку из показаний Мамаджанова и тушит сигарету о край стола, мимо пепельницы.\n— Сдал, значит, Фархад-ака. Ну да. Было. В девяносто третьем он мне полторы тысячи дал, на операцию матери, я не вернул. А девятого, в субботу, в чайхане у Зелёного — недели за две до всего — говорит: спишу, только скажи, когда Игорь без водилы ездит, поговорить надо по-мужски. Я сказал: по четвергам. В четверг пришло на пейджер «в силе?» — я перезвонил, подтвердил. Больше ничего не знал, хоть режь. Думал, разговор. В субботу был на смене, с двадцати до восьми, отзвоны на пульт каждый час. Проверяй.", "grants": ["b229ab87-5e5b-5f61-8a7b-18c17718e4cf"]}]'::jsonb, null, false, true, true, (select portrait_url from characters where name ilike 'Ерлан%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1));
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('631694f6-0ec1-523d-9f2a-599f875223c1', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', 'Тамара Фёдоровна Шнайдер', 'Соседка Шмидтов через забор, вдова', 'Над забором соседнего двора показывается седая голова в шерстяном платке. Тамара Фёдоровна Шнайдер смотрит на вас с подозрением и надеждой сразу.
— Вы из милиции? Ну наконец хоть кто-то. Я думала, у нас тут никто никогда ничего не спросит.', '[{"q": "Вы давно здесь живёте?", "a": "— С пятьдесят восьмого года, деточка. Дети мои в Германии уже третий год, в Кёльне, а я жду документов. Каждый месяц пишу, каждый месяц отвечают: ждите. Пенсию тут дают с задержкой, там, говорят, вовремя. Я одна на всю улицу осталась из наших. Все уехали."}, {"q": "Как вы разглядели всё в темноте?", "a": "— А что там разглядывать, если я его в лицо знаю? Он ко мне заходил, спрашивал, не надо ли кому дом. Фара у «Волги» одна горела, правая, а он вышел прямо в свет, к калитке. Это было до того, как свет отключили, по радио новости как раз кончились. А потом темно стало везде, только у Шмидтов в окне керосинка. Я сама у окна с керосинкой сижу, когда света нет, мне не спится.", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"]}, {"q": "Почему вы не сообщили в милицию?", "a": "— А что я скажу? Что у соседей кто-то печку топит? Фархад сказал — люди въедут. Я и думала — въехали. И потом... Я с советского времени милицию боюсь, извините. Затаскают — и не выпустят к детям.", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"]}]'::jsonb, '{"c2c5ba62-e24e-523f-93bc-d8909b28e717": "Тамара Фёдоровна стоит у забора в пальто поверх халата и смотрит, как из люка поднимается Сеитова с пакетом.\n— Gott... Значит, там кто-то был. Я всё скажу, я же не сплю. Дом продаёт Фархад, он покупателей водил, я его в лицо знаю. В среду сказал: скоро въедут люди. В пятницу из трубы дым, под навесом тёмная иномарка, печь топил парень, высокий, молодой. В субботу в четверть седьмого — белая «Волга», одна фара. Вышли двое: Фархад, прямо в свет, и тот парень. Парень скоро ушёл пешком. Больше никто не приезжал, никаких покупателей. Потом свет отключили, а у Шмидтов керосинка до ночи. В двадцать минут двенадцатого со двора выехала иномарка, без фар, — я её по мотору узнала, у наших так не урчит. А «Волга» у калитки стояла до половины второго. Уехала по свежему снегу.", "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba": "— Шмидты? Хорошие люди, весной уехали, сын у них давно там. Дом продаёт Фархад, по доверенности, я так понимаю: он покупателей водил, я его в лицо знаю. В среду сказал: скоро въедут люди. Я и думала — въехали. В пятницу из трубы дым, под навесом тёмная машина, не наша, иномарка. Печку топил парень, высокий, молодой. В субботу в четверть седьмого, по радио как раз новости кончились, — белая «Волга», одна фара горит. Вышли Фархад и тот парень, парень скоро ушёл пешком. Покупателей никаких, ну, ja, кто ж в темноте дом смотрит. Потом свет отключили, и до ночи у Шмидтов одно окно — керосинка. В двадцать минут двенадцатого выехала та иномарка, без фар, я её по мотору узнала. А «Волга» до половины второго стояла."}'::jsonb, '[{"id": "R18", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": [], "text": "Тамара Фёдоровна стоит у забора в пальто поверх халата и смотрит, как из люка поднимается Сеитова с пакетом.\n— Gott... Значит, там кто-то был. Я всё скажу, я же не сплю. Дом продаёт Фархад, он покупателей водил, я его в лицо знаю. В среду сказал: скоро въедут люди. В пятницу из трубы дым, под навесом тёмная иномарка, печь топил парень, высокий, молодой. В субботу в четверть седьмого — белая «Волга», одна фара. Вышли двое: Фархад, прямо в свет, и тот парень. Парень скоро ушёл пешком. Больше никто не приезжал, никаких покупателей. Потом свет отключили, а у Шмидтов керосинка до ночи. В двадцать минут двенадцатого со двора выехала иномарка, без фар, — я её по мотору узнала, у наших так не урчит. А «Волга» у калитки стояла до половины второго. Уехала по свежему снегу.", "grants": ["f725c4c5-f254-5c01-b718-3531a957102a"]}, {"id": "R19", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": [], "text": "— Шмидты? Хорошие люди, весной уехали, сын у них давно там. Дом продаёт Фархад, по доверенности, я так понимаю: он покупателей водил, я его в лицо знаю. В среду сказал: скоро въедут люди. Я и думала — въехали. В пятницу из трубы дым, под навесом тёмная машина, не наша, иномарка. Печку топил парень, высокий, молодой. В субботу в четверть седьмого, по радио как раз новости кончились, — белая «Волга», одна фара горит. Вышли Фархад и тот парень, парень скоро ушёл пешком. Покупателей никаких, ну, ja, кто ж в темноте дом смотрит. Потом свет отключили, и до ночи у Шмидтов одно окно — керосинка. В двадцать минут двенадцатого выехала та иномарка, без фар, я её по мотору узнала. А «Волга» до половины второго стояла.", "grants": ["f725c4c5-f254-5c01-b718-3531a957102a"]}]'::jsonb, null, false, false, true, null);
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('ea6167fb-4eea-5e08-ae65-e5fce24e6a6c', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', 'Олжас Бекенов', 'Сын двоюродной сестры Фархада, из аула под Талгаром', 'Олжас Бекенов — высокий, худой, с обветренным лицом и большими руками грузчика. Сидит на койке и смотрит в пол. На удостоверение даже не поднимает глаз.
— Мен не знаю ничего.', '[{"q": "Ты знаешь Игоря Сартакова?", "a": "— Не знаю. Такого не знаю. Я на базаре работаю, мешки. Кто такой — не знаю."}, {"q": "Где ты был в четверг вечером и в субботу?", "a": "— На базаре. Потом в общаге. Вахтёрша скажет. Ребята скажут. Всё."}, {"q": "Откуда у тебя три тысячи долларов?", "a": "— Заработал. Копил. Мешки таскаю, два года. — Он поднимает глаза и тут же опускает. — Матери на дом копил.", "requires": ["46e78eb0-d057-5e5d-8a00-81457f8f3d20"]}, {"q": "Как ты обращался с пленником?", "a": "— Чай носил. Хлеб. Он со мной через люк разговаривал. Про дочку свою, что ей двенадцать. Нормальный мужик был, не ругался. Я мешок ему на голову не стал туго... не смог. Мен не зверь.", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"]}, {"q": "Что ты скажешь матери?", "a": "— Ничего. — Долгая пауза. — Она думает, я в городе учусь. Ойбай... Скажите ей, что я сам. Что аке тут... Нет. Ничего не говорите.", "requires": ["3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"]}]'::jsonb, '{"d91852b9-daca-5340-80c9-a13cffe680cc": "В кабинете Олжас сидит на краешке стула, большие руки зажаты между коленями. Вы кладёте перед ним протокол сравнения купюр и показания соседки Шмидтов. Он смотрит в пол. Долго. Потом его словно прорывает:\n— Ойбай... Ладно. Я. Я его взял, у ворот, в четверг, темно уже было. Машину его к Шмидтам перегнал, под навес, — водить умею, прав только нет. Держал его в подвале у немцев. Кормил, чай носил, не бил, клянусь. Матери его звонил из автоматов, а в субботу автомат на остановке сломан был, я из того дома позвонил. Пакет на остановке я забрал. Деньги оттуда, да. Но аке ни при чём! Слышите? Я сам всё придумал. Сам. Утром его отпустили... ну, отпустил кто-то, машина его там же, под навесом, стояла — сел и поехал к себе на дачу. И угорел. Бог наказал. Я его не трогал.", "54bf13bc-3525-5eec-9441-609d8ee21f59": "В кабинете, на столе — вспоротый мешок с рисом и протокол обыска. Олжаса и Фархада сажают друг напротив друга; между ними стол и понятой, который старается ни на кого не смотреть. Вы зачитываете Олжасу заключение Кана: задушен в субботу около десяти вечера, в машину посажен мёртвым. И говорите, где лежали остальные деньги.\nОлжас поворачивается к дяде.\n— Аке... Ты же сказал — утром отпустишь. За городом. — Голос у него садится. — Ты меня за остановкой подобрал, мы вдвоём приехали, там, кроме нас, только он был. Я тебе в четверть седьмого всё передал, как он просил: «Фархад, я тебя узнал. Бери деньги и отпусти, никому не скажу». Он тебя через мешок узнал, аке. По кашлю. И «Беломором» от тебя пахло, когда ты ему воду спускал. Ты молчал. Три тысячи мне отсчитал. Без четверти семь сказал: иди в общагу. Я пошёл. — Он закрывает лицо руками. — Это я тебе сказал. Если б я не сказал...", "ed68230f-dcda-56e7-a77c-ecd7a4cc05a4": "В кабинете вы кладёте перед Олжасом журнал вахтёрши и заключение Кана о царапинах на кисти дяди. Задушен в субботу около десяти вечера.\n— Да, в общаге был. С полвосьмого. — Он смотрит на строчку, потом на бумагу Кана, и вы видите, как до него доходит. — Значит... Я в общаге, а с ним остался аке. Один. Мы ж вдвоём туда приехали, больше никого не было. И Игорь его ногтями... в десять вечера... — Пауза. — Я в четверть седьмого ему передал. Слова Игоря: «Фархад, я тебя узнал. Бери деньги и отпусти, никому не скажу». Он тебя через мешок узнал, аке. По кашлю. И «Беломором» от тебя пахло, когда ты ему воду спускал. Аке ничего не ответил. Деньги все забрал, мне три тысячи отсчитал. Без четверти семь отправил меня: иди, утром отпущу его за городом. Ойбай... Он же мне сказал — никто не пострадает.", "c2c5ba62-e24e-523f-93bc-d8909b28e717": "Вы кладёте перед Олжасом серый шарф из подвала и пересказываете, что видели Данияр на остановке и соседка у дома Шмидтов: высокий, молодой, спортивная куртка, ушанка; печь топил.\nОлжас смотрит на шарф и не может отвести глаз.\n— Он мёрз там... — И сразу, быстро, как с горы: — Я его взял. В четверг, у ворот, темно было. Машину его к Шмидтам перегнал — водить умею, прав нет. В подвале держал. Матери его звонил из автоматов, а в субботу из того дома, там телефон. Пакет на остановке забрал я. Но аке ни при чём! Я сам придумал, слышите? Сам. А утром его отпустили, машину ему отдали — она там же, под навесом, стояла, — он на дачу поехал и угорел. Бог наказал. Не я.\nСосед по комнате перестаёт притворяться спящим. На запястьях Олжаса щёлкают наручники."}'::jsonb, '[{"id": "R25", "on": "d91852b9-daca-5340-80c9-a13cffe680cc", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "В кабинете Олжас сидит на краешке стула, большие руки зажаты между коленями. Вы кладёте перед ним протокол сравнения купюр и показания соседки Шмидтов. Он смотрит в пол. Долго. Потом его словно прорывает:\n— Ойбай... Ладно. Я. Я его взял, у ворот, в четверг, темно уже было. Машину его к Шмидтам перегнал, под навес, — водить умею, прав только нет. Держал его в подвале у немцев. Кормил, чай носил, не бил, клянусь. Матери его звонил из автоматов, а в субботу автомат на остановке сломан был, я из того дома позвонил. Пакет на остановке я забрал. Деньги оттуда, да. Но аке ни при чём! Слышите? Я сам всё придумал. Сам. Утром его отпустили... ну, отпустил кто-то, машина его там же, под навесом, стояла — сел и поехал к себе на дачу. И угорел. Бог наказал. Я его не трогал.", "grants": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"]}, {"id": "R26", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d", "107fcb2c-e909-5f81-bba4-d218265227c5"], "text": "В кабинете, на столе — вспоротый мешок с рисом и протокол обыска. Олжаса и Фархада сажают друг напротив друга; между ними стол и понятой, который старается ни на кого не смотреть. Вы зачитываете Олжасу заключение Кана: задушен в субботу около десяти вечера, в машину посажен мёртвым. И говорите, где лежали остальные деньги.\nОлжас поворачивается к дяде.\n— Аке... Ты же сказал — утром отпустишь. За городом. — Голос у него садится. — Ты меня за остановкой подобрал, мы вдвоём приехали, там, кроме нас, только он был. Я тебе в четверть седьмого всё передал, как он просил: «Фархад, я тебя узнал. Бери деньги и отпусти, никому не скажу». Он тебя через мешок узнал, аке. По кашлю. И «Беломором» от тебя пахло, когда ты ему воду спускал. Ты молчал. Три тысячи мне отсчитал. Без четверти семь сказал: иди в общагу. Я пошёл. — Он закрывает лицо руками. — Это я тебе сказал. Если б я не сказал...", "grants": ["3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"]}, {"id": "R41", "on": "ed68230f-dcda-56e7-a77c-ecd7a4cc05a4", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d", "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3"], "text": "В кабинете вы кладёте перед Олжасом журнал вахтёрши и заключение Кана о царапинах на кисти дяди. Задушен в субботу около десяти вечера.\n— Да, в общаге был. С полвосьмого. — Он смотрит на строчку, потом на бумагу Кана, и вы видите, как до него доходит. — Значит... Я в общаге, а с ним остался аке. Один. Мы ж вдвоём туда приехали, больше никого не было. И Игорь его ногтями... в десять вечера... — Пауза. — Я в четверть седьмого ему передал. Слова Игоря: «Фархад, я тебя узнал. Бери деньги и отпусти, никому не скажу». Он тебя через мешок узнал, аке. По кашлю. И «Беломором» от тебя пахло, когда ты ему воду спускал. Аке ничего не ответил. Деньги все забрал, мне три тысячи отсчитал. Без четверти семь отправил меня: иди, утром отпущу его за городом. Ойбай... Он же мне сказал — никто не пострадает.", "grants": ["3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"]}, {"id": "R42", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a", "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e"], "text": "Вы кладёте перед Олжасом серый шарф из подвала и пересказываете, что видели Данияр на остановке и соседка у дома Шмидтов: высокий, молодой, спортивная куртка, ушанка; печь топил.\nОлжас смотрит на шарф и не может отвести глаз.\n— Он мёрз там... — И сразу, быстро, как с горы: — Я его взял. В четверг, у ворот, темно было. Машину его к Шмидтам перегнал — водить умею, прав нет. В подвале держал. Матери его звонил из автоматов, а в субботу из того дома, там телефон. Пакет на остановке забрал я. Но аке ни при чём! Я сам придумал, слышите? Сам. А утром его отпустили, машину ему отдали — она там же, под навесом, стояла, — он на дачу поехал и угорел. Бог наказал. Не я.\nСосед по комнате перестаёт притворяться спящим. На запястьях Олжаса щёлкают наручники.", "grants": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"]}]'::jsonb, null, false, true, true, (select portrait_url from characters where name ilike '%Олжас%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1));

