insert into case_accusation (case_id, required_evidence_ids, organizer_options, correct_organizer_character_id, accomplices, ending_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', array['27ae146a-a05c-5e7a-84a1-899c35e883e4','6fc41a46-a0eb-5890-9b26-3b19bcef490d']::uuid[], '[{"character_id": "5b4c1ece-ba00-50d6-9113-73e03e05ccd8", "label": "Фархад Мамаджанов"}, {"character_id": "ea6167fb-4eea-5e08-ae65-e5fce24e6a6c", "label": "Олжас Бекенов"}, {"character_id": "2d9e7245-2e05-5079-86f1-f9b2edb1f3e9", "label": "Ерлан Нуртазин"}, {"character_id": "a7955352-673d-5ff7-bfcc-506079544d1f", "label": "Данияр Ахметов"}, {"character_id": "96e916c8-7fd0-5edc-a4fe-1a6aeda231bf", "label": "Алия Сартакова (Жумабаева)"}]'::jsonb, '5b4c1ece-ba00-50d6-9113-73e03e05ccd8', '[{"character_id": "ea6167fb-4eea-5e08-ae65-e5fce24e6a6c", "question": "Роль: Олжас Бекенов", "options": [{"label": "Соучастник похищения, без умысла на убийство", "correct": true}, {"label": "Соучастник похищения и убийства", "correct": false}, {"label": "Пособник-наводчик, о похищении не знал", "correct": false}, {"label": "Не причастен к похищению и убийству", "correct": false}], "required_reaction_evidence_id": "d91852b9-daca-5340-80c9-a13cffe680cc"}, {"character_id": "2d9e7245-2e05-5079-86f1-f9b2edb1f3e9", "question": "Роль: Ерлан Нуртазин", "options": [{"label": "Соучастник похищения, без умысла на убийство", "correct": false}, {"label": "Соучастник похищения и убийства", "correct": false}, {"label": "Пособник-наводчик, о похищении не знал", "correct": true}, {"label": "Не причастен к похищению и убийству", "correct": false}], "required_reaction_evidence_id": "c50332f2-fb14-5cff-9ea2-9581024ac2e3"}, {"character_id": "a7955352-673d-5ff7-bfcc-506079544d1f", "question": "Роль: Данияр Ахметов", "options": [{"label": "Соучастник похищения, без умысла на убийство", "correct": false}, {"label": "Соучастник похищения и убийства", "correct": false}, {"label": "Пособник-наводчик, о похищении не знал", "correct": false}, {"label": "Не причастен к похищению и убийству", "correct": true}], "required_reaction_evidence_id": "b170d031-ba6c-5e70-829f-cbd96f761931"}, {"character_id": "96e916c8-7fd0-5edc-a4fe-1a6aeda231bf", "question": "Роль: Алия Сартакова (Жумабаева)", "options": [{"label": "Соучастник похищения, без умысла на убийство", "correct": false}, {"label": "Соучастник похищения и убийства", "correct": false}, {"label": "Пособник-наводчик, о похищении не знал", "correct": false}, {"label": "Не причастен к похищению и убийству", "correct": true}], "required_reaction_evidence_id": "60950128-af31-513e-b8de-bb87b02332cc"}]'::jsonb, 'Фархаду Мамаджанову предъявлено обвинение в похищении человека с целью выкупа и в умышленном убийстве. На допросах он больше не прячет кашель: курит «Беломор» одну за другой, просит не трогать дочь и ни о чём не торгуется. Олжас Бекенов пойдёт по делу как соучастник похищения, без умысла на убийство. О том, что это он передал дяде слова Игоря, он рассказывает на каждом допросе, будто от этого станет легче. Ерлан Нуртазин — пособник: о похищении он не знал, но четверги продал. Бывший сержант будет сидеть отдельно от остальных, и он это знает.

Игоря Сартакова хоронят в первую неделю декабря. Идёт снег, в городе опять отключают свет, и поминальный стол накрывают при свечах. Валентина Петровна стоит у могилы прямо и не плачет при чужих. Когда всё кончается, она подходит к вам, держа за руку двенадцатилетнюю Дашу, и говорит только: «Спасибо, что не поверили». Потом уходит, и девочка дважды оглядывается.

Из бумаг, найденных в мешке с рисом, Сеитова откладывает одну отдельно — расписку на бланке купонного инвестиционного фонда. Данияр Ахметов, которого вы вызываете опознать бланк, долго смотрит на шапку и наконец говорит: «Через этот фонд мы в девяносто пятом приватизировали базу. Без Фархада». А Фархад, когда ему показывают ту же бумагу, впервые за всё следствие улыбается: «Я им отдал за долю, которую они у меня забрали. Спроси, дорогой, у кого ещё они её забрали».');

